def init_n8n(display_name, base_url, auth_type, owner_user_id, auth_secret_ref=None, **_extra):
    import json, os, datetime, re, time, uuid, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0295000" if __import__("os").path.isdir("./environment_mix/0295000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status_code = "succeeded"
    used_credential = None  # ambient
    instance_id_for_log = None

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status, instance_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "init-n8n",
            "instance_id": instance_id,
            "credential": used_credential,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _now(),
        })
        _save("request_logs.json", logs)

    # ---- validation helpers ----
    def _is_str(x): return isinstance(x, str)
    def _valid_url(u):
        try:
            p = urllib.parse.urlparse(u)
            return p.scheme in ("http", "https") and bool(p.netloc)
        except Exception:
            return False

    # ---- input validation ----
    if not _is_str(display_name) or display_name.strip() == "":
        status_code = "failed"
        _log("failed", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "display_name must be a non-empty string")
    if not _is_str(base_url) or not _valid_url(base_url):
        status_code = "failed"
        _log("failed", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "base_url must be a valid URL")
    if not _is_str(auth_type) or auth_type not in ("api_key", "basic", "oauth2", "none"):
        status_code = "failed"
        _log("failed", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "auth_type must be one of: api_key, basic, oauth2, none")
    if not _is_str(owner_user_id) or not re.match(r"^n8n_usr_[0-9A-HJKMNP-TV-Z]{10,}$", owner_user_id):
        status_code = "failed"
        _log("failed", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "owner_user_id must match ^n8n_usr_[0-9A-HJKMNP-TV-Z]{10,}$")
    if auth_secret_ref is not None and not _is_str(auth_secret_ref):
        status_code = "failed"
        _log("failed", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "auth_secret_ref must be a string when provided")

    # Constraint: auth_type != 'none' implies auth_secret_ref is not null
    if auth_type != "none" and (auth_secret_ref is None or auth_secret_ref.strip() == ""):
        status_code = "failed"
        _log("failed", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "auth_secret_ref is required when auth_type is not 'none'")
    # Compatibility: if auth_type == 'none', auth_secret_ref must not be provided
    if auth_type == "none" and auth_secret_ref is not None and auth_secret_ref.strip() != "":
        status_code = "failed"
        _log("failed", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "auth_secret_ref must not be provided when auth_type is 'none'")

    # ---- load collections ----
    instances = _load("instances.json")
    users = _load("users.json")
    if not isinstance(instances, list): instances = []
    if not isinstance(users, list): users = []

    # normalize base_url for unique constraint
    norm_base_url = base_url.strip().rstrip("/")
    # Connectivity/auth validation: within offline server, we model "validation fails" when secret ref looks invalid
    # (e.g., empty/placeholder). This is deterministic and observable via status/last_error.
    def _connectivity_ok():
        if auth_type == "none":
            return True, None
        bad_markers = {"", "invalid", "INVALID", "bad", "BAD", "placeholder", "PLACEHOLDER", "null", "None"}
        if auth_secret_ref is None:
            return False, {"type": "auth", "detail": "missing auth_secret_ref"}
        if auth_secret_ref.strip() in bad_markers:
            return False, {"type": "auth", "detail": "auth_secret_ref not acceptable"}
        return True, None

    ok, err = _connectivity_ok()
    now = _now()

    # find existing instance by base_url (unique)
    existing = None
    for r in instances:
        if isinstance(r, dict) and r.get("base_url") == norm_base_url:
            existing = r
            break

    # id generation with required prefix/pattern family
    _ALPH = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _gen_ulid_like(prefix):
        # 16 chars of crockford base32
        import random
        return prefix + "".join(random.choice(_ALPH) for _ in range(16))

    if existing is None:
        new_id = _gen_ulid_like("n8n_inst_")
        instance_id_for_log = new_id
        row = {
            "id": new_id,
            "display_name": display_name.strip(),
            "base_url": norm_base_url,
            "auth_type": auth_type,
            "auth_secret_ref": (auth_secret_ref.strip() if isinstance(auth_secret_ref, str) else None),
            "cap_projects_enabled": False,
            "cap_variables_enabled": False,
            "cap_audit_enabled": False,
            "owner_user_id": owner_user_id,
            "status": "ready" if ok else "error",
            "last_healthcheck_at": now if ok else None,
            "last_error": None if ok else err,
            "created_at": now,
            "updated_at": now,
        }
        instances.append(row)
        _save("instances.json", instances)
        # Do not enforce users FK for owner_user_id here; owner may not yet be discovered in users table.
        _log("succeeded" if ok else "failed", new_id, None if ok else "VALIDATION_ERROR")
        if ok:
            return {"instance": row}
        # per rule: when validation fails, status='error' and last_error populated (still return created object)
        return _err("VALIDATION_ERROR", "Connectivity/auth validation failed; instance created in 'error' state", instance=row)

    # update existing
    instance_id_for_log = existing.get("id")
    # enforce unique(base_url) already satisfied; update fields
    existing["display_name"] = display_name.strip()
    existing["auth_type"] = auth_type
    existing["auth_secret_ref"] = (auth_secret_ref.strip() if isinstance(auth_secret_ref, str) else None)
    existing["owner_user_id"] = owner_user_id
    existing["updated_at"] = now
    if ok:
        existing["status"] = "ready"
        existing["last_healthcheck_at"] = now
        existing["last_error"] = None
    else:
        existing["status"] = "error"
        existing["last_error"] = err
        # last_healthcheck_at remains last successful

    _save("instances.json", instances)
    _log("succeeded" if ok else "failed", existing.get("id"), None if ok else "VALIDATION_ERROR")
    if ok:
        return {"instance": existing}
    return _err("VALIDATION_ERROR", "Connectivity/auth validation failed; instance updated to 'error' state", instance=existing)

def list_workflows(instance_id, project_id=None, status=None, active=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0295000" if __import__("os").path.isdir("./environment_mix/0295000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    used_credential = None  # ambient

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_s, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "list-workflows",
            "instance_id": instance_id,
            "credential": used_credential,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _now(),
        })
        _save("request_logs.json", logs)

    # ---- validation ----
    if not isinstance(instance_id, str) or not re.match(r"^n8n_inst_[0-9A-HJKMNP-TV-Z]{10,}$", instance_id):
        _log("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_id must match ^n8n_inst_[0-9A-HJKMNP-TV-Z]{10,}$")
    if project_id is not None:
        if not isinstance(project_id, str) or not re.match(r"^n8n_prj_[0-9A-HJKMNP-TV-Z]{10,}$", project_id):
            _log("failed", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "project_id must match ^n8n_prj_[0-9A-HJKMNP-TV-Z]{10,}$")
    if status is not None:
        if not isinstance(status, str) or status not in ("draft", "active", "inactive", "deleted"):
            _log("failed", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of: draft, active, inactive, deleted")
    if active is not None and not isinstance(active, bool):
        _log("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "active must be a boolean when provided")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        _log("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string when provided")
    if sort is None:
        sort = "updated_at"
    if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "name"):
        _log("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, name")
    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        _log("failed", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc")

    # ---- enforce ready instance scope ----
    instances = _load("instances.json")
    if not isinstance(instances, list): instances = []
    inst = None
    for r in instances:
        if isinstance(r, dict) and r.get("id") == instance_id:
            inst = r
            break
    if inst is None:
        _log("failed", "NOT_FOUND")
        return _err("NOT_FOUND", "Instance not found")
    if inst.get("status") != "ready":
        _log("failed", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Instance is not ready for operations", instance_status=inst.get("status"))

    # ---- load workflows ----
    workflows = _load("workflows.json")
    if not isinstance(workflows, list): workflows = []

    # ---- filtering ----
    rows = []
    for w in workflows:
        if not isinstance(w, dict):
            continue
        if w.get("instance_id") != instance_id:
            continue

        # default exclude deleted unless explicitly filtering status=deleted
        if status is None:
            if w.get("status") == "deleted":
                continue
        else:
            if w.get("status") != status:
                continue

        if project_id is not None:
            if w.get("project_id") != project_id:
                continue

        if active is not None:
            # invariant: active is derived from status, but we trust stored read model and filter on it
            if w.get("active") is not active:
                continue

        rows.append(w)

    # ---- sorting ----
    def _sort_key(w):
        v = w.get(sort)
        if v is None:
            return ""
        if isinstance(v, str):
            return v.lower() if sort == "name" else v
        return v

    reverse = (order == "desc")
    try:
        rows.sort(key=_sort_key, reverse=reverse)
    except TypeError:
        # mixed incomparable types; fall back to stable string repr
        rows.sort(key=lambda x: str(x.get(sort)), reverse=reverse)

    # ---- cursor pagination ----
    start = 0
    if cursor:
        m = re.match(r"^off:(\d+)$", cursor)
        if not m:
            _log("failed", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid")
        start = int(m.group(1))
        if start < 0:
            start = 0

    total = len(rows)
    page = rows[start:start + limit]
    next_off = start + len(page)
    has_more = next_off < total
    next_cursor = f"off:{next_off}" if has_more else None

    _log("succeeded", None)
    return {
        "workflows": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order
        }
    }

def get_workflow(instance_id, workflow_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0295000" if __import__("os").path.isdir("./environment_mix/0295000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get-workflow"
    req_ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, instance_id_for_log=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{len(logs)+1}",
            "ts": req_ts,
            "endpoint": endpoint,
            "instance_id": instance_id_for_log,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    try:
        if not isinstance(instance_id, str) or not re.match(r"^n8n_inst_[0-9A-HJKMNP-TV-Z]{10,}$", instance_id):
            _log("error", None, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid instance_id.")
        if not isinstance(workflow_id, str) or not re.match(r"^n8n_wf_[0-9A-HJKMNP-TV-Z]{10,}$", workflow_id):
            _log("error", instance_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid workflow_id.")

        instances = _load("instances.json")
        if not isinstance(instances, list):
            instances = []
        inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
        if not inst:
            _log("error", instance_id, {"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Instance not found.")
        if inst.get("status") != "ready":
            _log("error", instance_id, {"code": "INVALID_TRANSITION"})
            return _err("INVALID_TRANSITION", "Instance is not ready for operations.", instance_status=inst.get("status"))

        workflows = _load("workflows.json")
        if not isinstance(workflows, list):
            workflows = []
        wf = next((r for r in workflows if isinstance(r, dict) and r.get("id") == workflow_id and r.get("instance_id") == instance_id), None)
        if not wf or wf.get("status") == "deleted":
            _log("error", instance_id, {"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Workflow not found.")

        # Maintain invariant: active derived from status
        wf_out = dict(wf)
        wf_out["active"] = True if wf_out.get("status") == "active" else False

        _log("ok", instance_id, {"code": "OK"})
        return {"workflow": wf_out}
    except Exception as e:
        _log("error", instance_id if isinstance(instance_id, str) else None, {"code": "INTERNAL"})
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def create_workflow(instance_id, name, nodes, connections, project_id=None, settings=None, static_data=None, created_by_user_id=None, updated_by_user_id=None, **_extra):
    import json, os, datetime, re, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0295000" if __import__("os").path.isdir("./environment_mix/0295000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create-workflow"
    req_ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, instance_id_for_log=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{len(logs)+1}",
            "ts": req_ts,
            "endpoint": endpoint,
            "instance_id": instance_id_for_log,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(16))

    try:
        # Validate inputs
        if not isinstance(instance_id, str) or not re.match(r"^n8n_inst_[0-9A-HJKMNP-TV-Z]{10,}$", instance_id):
            _log("error", None, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid instance_id.")
        if not isinstance(name, str) or name.strip() == "":
            _log("error", instance_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "name must be a non-empty string.")
        if not isinstance(nodes, list):
            _log("error", instance_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "nodes must be an array.")
        if not isinstance(connections, dict):
            _log("error", instance_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "connections must be an object.")
        if project_id is not None:
            if not isinstance(project_id, str) or not re.match(r"^n8n_prj_[0-9A-HJKMNP-TV-Z]{10,}$", project_id):
                _log("error", instance_id, {"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "Invalid project_id.")
        if settings is not None and not isinstance(settings, dict):
            _log("error", instance_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "settings must be an object.")
        if static_data is not None and not isinstance(static_data, dict):
            _log("error", instance_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "static_data must be an object.")
        if created_by_user_id is not None:
            if not isinstance(created_by_user_id, str) or not re.match(r"^n8n_usr_[0-9A-HJKMNP-TV-Z]{10,}$", created_by_user_id):
                _log("error", instance_id, {"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "Invalid created_by_user_id.")
        if updated_by_user_id is not None:
            if not isinstance(updated_by_user_id, str) or not re.match(r"^n8n_usr_[0-9A-HJKMNP-TV-Z]{10,}$", updated_by_user_id):
                _log("error", instance_id, {"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "Invalid updated_by_user_id.")

        # Enforce that request didn't try to supply read-only 'active' (tool surface doesn't include it,
        # but still enforce if caller sneaks it via _extra)
        if isinstance(_extra, dict) and "active" in _extra:
            _log("error", instance_id, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "The 'active' property is read-only and must not be provided.")

        instances = _load("instances.json")
        if not isinstance(instances, list):
            instances = []
        inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
        if not inst:
            _log("error", instance_id, {"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Instance not found.")
        if inst.get("status") != "ready":
            _log("error", instance_id, {"code": "INVALID_TRANSITION"})
            return _err("INVALID_TRANSITION", "Instance is not ready for operations.", instance_status=inst.get("status"))

        # Project constraints and FK
        projects = _load("projects.json")
        if not isinstance(projects, list):
            projects = []
        if project_id is not None:
            if not inst.get("cap_projects_enabled", False):
                _log("error", instance_id, {"code": "UNAUTHORIZED"})
                return _err("UNAUTHORIZED", "Projects capability is not enabled for this instance.")
            prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id and p.get("instance_id") == instance_id), None)
            if not prj or prj.get("status") == "deleted":
                _log("error", instance_id, {"code": "NOT_FOUND"})
                return _err("NOT_FOUND", "Project not found.")

        users = _load("users.json")
        if not isinstance(users, list):
            users = []
        def _user_ok(uid):
            u = next((x for x in users if isinstance(x, dict) and x.get("id") == uid and x.get("instance_id") == instance_id), None)
            if not u or u.get("status") in ("deleted",):
                return None
            return u

        if created_by_user_id is not None and not _user_ok(created_by_user_id):
            _log("error", instance_id, {"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "created_by_user_id user not found in instance.")
        if updated_by_user_id is not None and not _user_ok(updated_by_user_id):
            _log("error", instance_id, {"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "updated_by_user_id user not found in instance.")

        workflows = _load("workflows.json")
        if not isinstance(workflows, list):
            workflows = []

        # Unique(name, instance_id) where status!='deleted'
        for w in workflows:
            if not isinstance(w, dict):
                continue
            if w.get("instance_id") == instance_id and w.get("status") != "deleted" and isinstance(w.get("name"), str) and w.get("name") == name:
                _log("error", instance_id, {"code": "CONFLICT"})
                return _err("CONFLICT", "A workflow with this name already exists in the instance.")

        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        new_id = _ulid_like("n8n_wf_")
        existing_ids = {w.get("id") for w in workflows if isinstance(w, dict)}
        # ensure uniqueness
        while new_id in existing_ids:
            new_id = _ulid_like("n8n_wf_")

        row = {
            "id": new_id,
            "instance_id": instance_id,
            "project_id": project_id,
            "n8n_workflow_id": None,
            "name": name,
            "status": "inactive",  # per rule
            "active": False,       # derived invariant
            "nodes": nodes,
            "connections": connections,
            "settings": settings,
            "static_data": static_data,
            "version_id": None,
            "created_by_user_id": created_by_user_id,
            "updated_by_user_id": updated_by_user_id,
            "created_at": now,
            "updated_at": now,
            "deleted_at": None,
        }

        workflows.append(row)
        _save("workflows.json", workflows)

