def update_workflow(instance_id, workflow_id, name=None, nodes=None, connections=None, settings=None, static_data=None, project_id=None, updated_by_user_id=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0295000" if __import__("os").path.isdir("./environment_mix/0295000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_log(status, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "update-workflow",
            "instance_id": instance_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        })
        _save("request_logs.json", logs)

    def _rate_limit_check():
        cfg = _load("service_config.json")
        if isinstance(cfg, dict):
            limit_per_min = cfg.get("rate_limit_per_minute")
            quota_per_day = cfg.get("quota_per_day")
        elif isinstance(cfg, list) and cfg and isinstance(cfg[0], dict):
            limit_per_min = cfg[0].get("rate_limit_per_minute")
            quota_per_day = cfg[0].get("quota_per_day")
        else:
            limit_per_min = None
            quota_per_day = None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None

        def _parse_ts(x):
            try:
                return datetime.datetime.fromisoformat(x.replace("Z", "+00:00"))
            except Exception:
                return None

        now_dt = _parse_ts(now)
        if not now_dt:
            return None

        inst_logs = []
        for r in logs:
            if isinstance(r, dict) and r.get("instance_id") == instance_id:
                ts = _parse_ts(r.get("timestamp", ""))
                if ts:
                    inst_logs.append((ts, r))

        if isinstance(limit_per_min, int) and limit_per_min >= 0:
            cut = now_dt - datetime.timedelta(seconds=60)
            cnt = sum(1 for ts, _ in inst_logs if ts >= cut)
            if cnt >= limit_per_min:
                return _err("RATE_LIMIT", "Rate limit exceeded")

        if isinstance(quota_per_day, int) and quota_per_day >= 0:
            cut = now_dt - datetime.timedelta(days=1)
            cnt = sum(1 for ts, _ in inst_logs if ts >= cut)
            if cnt >= quota_per_day:
                return _err("QUOTA_EXCEEDED", "Quota exceeded")
        return None

    # Validate inputs
    if not isinstance(instance_id, str) or not re.match(r"^n8n_inst_[0-9A-HJKMNP-TV-Z]{10,}$", instance_id):
        e = _err("VALIDATION_ERROR", "Invalid instance_id")
        _append_log("error", e["error"]["code"])
        return e
    if not isinstance(workflow_id, str) or not re.match(r"^n8n_wf_[0-9A-HJKMNP-TV-Z]{10,}$", workflow_id):
        e = _err("VALIDATION_ERROR", "Invalid workflow_id")
        _append_log("error", e["error"]["code"])
        return e
    if name is not None and (not isinstance(name, str) or name == ""):
        e = _err("VALIDATION_ERROR", "Invalid name")
        _append_log("error", e["error"]["code"])
        return e
    if nodes is not None and not isinstance(nodes, list):
        e = _err("VALIDATION_ERROR", "nodes must be an array")
        _append_log("error", e["error"]["code"])
        return e
    if connections is not None and not isinstance(connections, dict):
        e = _err("VALIDATION_ERROR", "connections must be an object")
        _append_log("error", e["error"]["code"])
        return e
    if settings is not None and not isinstance(settings, dict):
        e = _err("VALIDATION_ERROR", "settings must be an object")
        _append_log("error", e["error"]["code"])
        return e
    if static_data is not None and not isinstance(static_data, dict):
        e = _err("VALIDATION_ERROR", "static_data must be an object")
        _append_log("error", e["error"]["code"])
        return e
    if project_id is not None:
        if not isinstance(project_id, str) or not re.match(r"^n8n_prj_[0-9A-HJKMNP-TV-Z]{10,}$", project_id):
            e = _err("VALIDATION_ERROR", "Invalid project_id")
            _append_log("error", e["error"]["code"])
            return e
    if updated_by_user_id is not None:
        if not isinstance(updated_by_user_id, str) or not re.match(r"^n8n_usr_[0-9A-HJKMNP-TV-Z]{10,}$", updated_by_user_id):
            e = _err("VALIDATION_ERROR", "Invalid updated_by_user_id")
            _append_log("error", e["error"]["code"])
            return e

    rl = _rate_limit_check()
    if rl:
        _append_log("error", rl["error"]["code"])
        return rl

    instances = _load("instances.json")
    if not isinstance(instances, list):
        e = _err("UNAUTHORIZED", "No ready instance available")
        _append_log("error", e["error"]["code"])
        return e

    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if not inst:
        e = _err("NOT_FOUND", "Instance not found")
        _append_log("error", e["error"]["code"])
        return e
    if inst.get("status") != "ready":
        e = _err("UNAUTHORIZED", "Instance is not ready")
        _append_log("error", e["error"]["code"])
        return e

    workflows = _load("workflows.json")
    if not isinstance(workflows, list):
        workflows = []

    wf_idx = None
    wf = None
    for i, r in enumerate(workflows):
        if isinstance(r, dict) and r.get("id") == workflow_id and r.get("instance_id") == instance_id:
            wf_idx = i
            wf = r
            break
    if not wf:
        e = _err("NOT_FOUND", "Workflow not found")
        _append_log("error", e["error"]["code"])
        return e

    if wf.get("status") == "deleted":
        e = _err("NOT_FOUND", "Workflow not found")
        _append_log("error", e["error"]["code"])
        return e

    # Foreign keys / capability checks for project move
    if project_id is not None:
        if not inst.get("cap_projects_enabled", False):
            e = _err("UNAUTHORIZED", "Projects capability not enabled for this instance")
            _append_log("error", e["error"]["code"])
            return e
        projects = _load("projects.json")
        if not isinstance(projects, list):
            projects = []
        prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id and p.get("instance_id") == instance_id), None)
        if not prj or prj.get("status") == "deleted":
            e = _err("NOT_FOUND", "Project not found")
            _append_log("error", e["error"]["code"])
            return e

    # updated_by_user must exist in instance when provided
    if updated_by_user_id is not None:
        users = _load("users.json")
        if not isinstance(users, list):
            users = []
        usr = next((u for u in users if isinstance(u, dict) and u.get("id") == updated_by_user_id and u.get("instance_id") == instance_id), None)
        if not usr or usr.get("status") == "deleted":
            e = _err("NOT_FOUND", "User not found")
            _append_log("error", e["error"]["code"])
            return e

    # Uniqueness: unique(name, instance_id) where status!='deleted'
    if name is not None:
        for r in workflows:
            if not isinstance(r, dict):
                continue
            if r.get("id") == workflow_id:
                continue
            if r.get("instance_id") == instance_id and r.get("status") != "deleted" and r.get("name") == name:
                e = _err("CONFLICT", "Workflow name already exists in instance")
                _append_log("error", e["error"]["code"])
                return e

    # Must keep invariant active=(status=='active'); update does not change status here.
    changed = False

    if name is not None and wf.get("name") != name:
        wf["name"] = name
        changed = True
    if nodes is not None:
        wf["nodes"] = nodes
        changed = True
    if connections is not None:
        wf["connections"] = connections
        changed = True
    if settings is not None:
        wf["settings"] = settings
        changed = True
    if static_data is not None:
        wf["static_data"] = static_data
        changed = True
    if project_id is not None:
        wf["project_id"] = project_id
        changed = True
    if updated_by_user_id is not None:
        wf["updated_by_user_id"] = updated_by_user_id
        changed = True

    # Ensure required fields remain valid
    if "nodes" in wf and not isinstance(wf.get("nodes"), list):
        e = _err("VALIDATION_ERROR", "nodes must be an array")
        _append_log("error", e["error"]["code"])
        return e
    if "connections" in wf and not isinstance(wf.get("connections"), dict):
        e = _err("VALIDATION_ERROR", "connections must be an object")
        _append_log("error", e["error"]["code"])
        return e

    # If no effect, treat as NOT_FOUND-equivalent? Here it's an update with no changes; real APIs typically succeed.
    # To respect "no success without effect", require at least one change field provided and different.
    if not changed:
        e = _err("CONFLICT", "No changes to apply")
        _append_log("error", e["error"]["code"])
        return e

    wf["updated_at"] = now
    # derived invariant
    wf["active"] = True if wf.get("status") == "active" else False
    # bump version_id (optimistic concurrency token)
    wf["version_id"] = "ver_" + uuid.uuid4().hex

    workflows[wf_idx] = wf
    _save("workflows.json", workflows)

    _append_log("ok", None)
    return {"workflow": wf}

