            limit_per_min = cfg.get("rate_limit_per_minute") or cfg.get("requests_per_minute")
            quota_per_day = cfg.get("quota_per_day") or cfg.get("requests_per_day")
        elif isinstance(cfg, list) and cfg and isinstance(cfg[0], dict):
            limit_per_min = cfg[0].get("rate_limit_per_minute") or cfg[0].get("requests_per_minute")
            quota_per_day = cfg[0].get("quota_per_day") or cfg[0].get("requests_per_day")
        if limit_per_min is None and quota_per_day is None:
            return None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = _parse_ts(_now)
        if now_dt is None:
            return None

        inst_logs = []
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("instance_id") != instance_id:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is not None:
                inst_logs.append(ts)

        if limit_per_min is not None:
            try:
                rpm = int(limit_per_min)
                if rpm >= 0:
                    cutoff = now_dt - datetime.timedelta(seconds=60)
                    if sum(1 for ts in inst_logs if ts >= cutoff) >= rpm:
                        return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=rpm, instance_id=instance_id)
            except Exception:
                pass

        if quota_per_day is not None:
            try:
                qd = int(quota_per_day)
                if qd >= 0:
                    cutoff = now_dt - datetime.timedelta(days=1)
                    if sum(1 for ts in inst_logs if ts >= cutoff) >= qd:
                        return _err("QUOTA_EXCEEDED", "Daily quota exceeded", quota_per_day=qd, instance_id=instance_id)
            except Exception:
                pass
        return None

    if not isinstance(instance_id, str) or not re.match(r"^n8n_inst_[0-9A-HJKMNP-TV-Z]{10,}$", instance_id):
        out = _err("VALIDATION_ERROR", "Invalid instance_id")
        _log("error", out["error"]["code"])
        return out
    if not isinstance(workflow_id, str) or not re.match(r"^n8n_wf_[0-9A-HJKMNP-TV-Z]{10,}$", workflow_id):
        out = _err("VALIDATION_ERROR", "Invalid workflow_id")
        _log("error", out["error"]["code"])
        return out

    limited = _enforce_limits()
    if limited:
        _log("error", limited["error"]["code"])
        return limited

    instances = _load("instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if not inst:
        out = _err("NOT_FOUND", "Instance not found", instance_id=instance_id)
        _log("error", out["error"]["code"])
        return out
    if inst.get("status") != "ready":
        out = _err("INVALID_TRANSITION", "Instance is not ready for workflow operations", instance_status=inst.get("status"), required_status="ready", instance_id=instance_id)
        _log("error", out["error"]["code"])
        return out

    workflows = _load("workflows.json")
    if not isinstance(workflows, list):
        workflows = []
    wf_idx = None
    wf = None
    for i, r in enumerate(workflows):
        if isinstance(r, dict) and r.get("id") == workflow_id and r.get("instance_id") == instance_id:
            wf_idx = i
            wf = r
            break
    if wf is None:
        out = _err("NOT_FOUND", "Workflow not found in this instance", instance_id=instance_id, workflow_id=workflow_id)
        _log("error", out["error"]["code"])
        return out

    cur = wf.get("status")
    if cur == "inactive":
        _log("ok")
        return {"workflow": wf, "changed": False}

    # Business rule: deactivate only from active to inactive
    if cur != "active":
        out = _err("INVALID_TRANSITION", "Cannot deactivate workflow from current status (allowed: active)", from_status=cur, to_status="inactive", workflow_id=workflow_id)
        _log("error", out["error"]["code"])
        return out

    wf = dict(wf)
    wf["status"] = "inactive"
    wf["active"] = False
    wf["updated_at"] = _now
    wf["version_id"] = f"v_{int(time.time()*1000)}_{random.randrange(1000,9999)}"
    workflows[wf_idx] = wf
    _save("workflows.json", workflows)

    _log("ok")
    return {"workflow": wf, "changed": True}

def list_projects(instance_id, status=None, created_by_user_id=None, search=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0295000" if __import__("os").path.isdir("./environment_mix/0295000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _endpoint = "list-projects"

    def _log(status_code, instance_row=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256(f"{_endpoint}|{_now}|{time.time()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": _endpoint,
            "instance_id": instance_id if isinstance(instance_id, str) else None,
            "status": status_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now,
            "meta": extra or {}
        })
        _save("request_logs.json", logs)

    # -------- validation --------
    if not isinstance(instance_id, str) or not re.match(r"^n8n_inst_[0-9A-HJKMNP-TV-Z]{26}$", instance_id):
        _log("VALIDATION_ERROR", extra={"field": "instance_id"})
        return _err("VALIDATION_ERROR", "instance_id must be a valid n8n instance id.", field="instance_id")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted"):
            _log("VALIDATION_ERROR", extra={"field": "status"})
            return _err("VALIDATION_ERROR", "status must be one of: active, deleted.", field="status")

    if created_by_user_id is not None:
        if not isinstance(created_by_user_id, str) or not re.match(r"^n8n_usr_[0-9A-HJKMNP-TV-Z]{26}$", created_by_user_id):
            _log("VALIDATION_ERROR", extra={"field": "created_by_user_id"})
            return _err("VALIDATION_ERROR", "created_by_user_id must be a valid user id.", field="created_by_user_id")

    if search is not None and not isinstance(search, str):
        _log("VALIDATION_ERROR", extra={"field": "search"})
        return _err("VALIDATION_ERROR", "search must be a string.", field="search")

    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log("VALIDATION_ERROR", extra={"field": "limit"})
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
    else:
        limit = 50

    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR", extra={"field": "cursor"})
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")

    if sort is not None:
        if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "name"):
            _log("VALIDATION_ERROR", extra={"field": "sort"})
            return _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, name.", field="sort")
    else:
        sort = "created_at"

    if order is not None:
        if not isinstance(order, str) or order not in ("asc", "desc"):
            _log("VALIDATION_ERROR", extra={"field": "order"})
            return _err("VALIDATION_ERROR", "order must be one of: asc, desc.", field="order")
    else:
        order = "desc"

    # -------- auth / instance resolution (ambient) --------
    instances = _load("instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if inst is None:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Instance not found.", instance_id=instance_id)

    # enforce single ready instance rule (except init-n8n)
    if inst.get("status") != "ready":
        _log("INVALID_TRANSITION", inst, extra={"instance_status": inst.get("status")})
        return _err("INVALID_TRANSITION", "Instance is not ready for operations.", instance_status=inst.get("status"))

    # capability/license rule
    if not inst.get("cap_projects_enabled", False):
        _log("UNAUTHORIZED", inst, extra={"cap_projects_enabled": False})
        return _err("UNAUTHORIZED", "Projects API is not enabled for this instance (license/capability required).", capability="cap_projects_enabled")

    # -------- query --------
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    rows = [p for p in projects if isinstance(p, dict) and p.get("instance_id") == instance_id]

    if status is not None:
        rows = [p for p in rows if p.get("status") == status]
    else:
        # by default, list-projects behaves like list-workflows rule? no explicit default exclusion.
        # We'll keep both active and deleted unless filtered; however most APIs default to non-deleted.
        # Given tool has status filter including deleted, default to active to mirror common behavior.
        rows = [p for p in rows if p.get("status") != "deleted"]

    if created_by_user_id is not None:
        rows = [p for p in rows if p.get("created_by_user_id") == created_by_user_id]

    if search:
        s = search.lower()
        rows = [p for p in rows if isinstance(p.get("name"), str) and s in p["name"].lower()]

    def _key(p):
        v = p.get(sort)
        if sort in ("created_at", "updated_at"):
            return v or ""
        if sort == "name":
            return (p.get("name") or "").lower()
        return v or ""

    rows.sort(key=_key, reverse=(order == "desc"))

    # pagination via cursor as integer offset (opaque string)
    offset = 0
    if cursor:
        m = re.match(r"^offset:(\d+)$", cursor)
        if not m:
            _log("VALIDATION_ERROR", inst, extra={"field": "cursor"})
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        offset = int(m.group(1))
        if offset < 0:
            _log("VALIDATION_ERROR", inst, extra={"field": "cursor"})
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = f"offset:{next_offset}" if has_more else None

    _log("OK", inst, extra={"returned": len(page), "total": total})

    return {
        "projects": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order
        }
    }

