        out = _err("CONFLICT", "Enterprise project management is not enabled for this instance", instance_id=instance_id, required_capability="cap_projects_enabled")
        _log("error", out["error"]["code"])
        return out

    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    u = next((r for r in users if isinstance(r, dict) and r.get("id") == created_by_user_id and r.get("instance_id") == instance_id), None)
    if not u:
        out = _err("NOT_FOUND", "User not found in this instance", instance_id=instance_id, user_id=created_by_user_id)
