    if u.get("status") == "deleted":
        out = _err("CONFLICT", "Deleted user cannot create projects", user_id=created_by_user_id)
        _log("error", out["error"]["code"])
        return out

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    nm = name.strip()
    # unique(name, instance_id) where status='active' (case-sensitive per schema, but we'll enforce exact match)
    for p in projects:
        if not isinstance(p, dict):
            continue
        if p.get("instance_id") == instance_id and p.get("status") == "active" and p.get("name") == nm:
            out = _err("CONFLICT", "Project name already exists in this instance", instance_id=instance_id, name=nm)
