            return out

    def _new_ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(26))

    row = {
        "id": _new_ulid_like("n8n_prj_"),
        "instance_id": instance_id,
        "n8n_project_id": None,
        "name": nm,
        "status": "active",
        "created_by_user_id": created_by_user_id,
        "created_at": _now,
        "updated_at": _now,
        "deleted_at": None,
    }
    projects.append(row)
    _save("projects.json", projects)

    _log("ok")
    return {"project": row}

