        projects = []
    idx = None
    prj = None
    for i, r in enumerate(projects):
        if isinstance(r, dict) and r.get("id") == project_id and r.get("instance_id") == instance_id:
            idx = i
            prj = r
            break
    if prj is None:
        out = _err("NOT_FOUND", "Project not found in this instance", instance_id=instance_id, project_id=project_id)
        _log("error", out["error"]["code"])
        return out

    # Block deletion if any non-deleted workflows still reference it
    workflows = _load("workflows.json")
    if not isinstance(workflows, list):
        workflows = []
    has_refs = any(isinstance(w, dict) and w.get("instance_id") == instance_id and w.get("project_id") == project_id and w.get("status") != "deleted" for w in workflows)
    if has_refs and prj.get("status") != "deleted":
        out = _err("CONFLICT", "Project cannot be deleted while workflows still reference it (no cascade delete)", project_id=project_id, instance_id=instance_id)
        _log("error", out["error"]["code"])
        return out

    # Idempotent delete
    if prj.get("status") == "deleted":
        _log("ok")
        return {"project": prj, "changed": False}

    prj2 = dict(prj)
    prj2["status"] = "deleted"
    prj2["deleted_at"] = _now
    prj2["updated_at"] = _now
    projects[idx] = prj2
    _save("projects.json", projects)

    _log("ok")
    return {"project": prj2, "changed": True}

def update_project(instance_id, project_id, name, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0295000" if __import__("os").path.isdir("./environment_mix/0295000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, used_instance_id=None, details=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        entry = {
            "id": "req_" + hashlib.sha256(f"{now}|{time.time_ns()}|update-project".encode("utf-8")).hexdigest()[:24],
            "endpoint": "update-project",
            "instance_id": used_instance_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
        if details is not None:
            entry["details"] = details
        logs.append(entry)
        _save("request_logs.json", logs)

    inst_pat = re.compile(r"^n8n_inst_[0-9A-HJKMNP-TV-Z]{26}$")
    prj_pat = re.compile(r"^n8n_prj_[0-9A-HJKMNP-TV-Z]{26}$")

    if not isinstance(instance_id, str) or not inst_pat.match(instance_id):
        _log("VALIDATION_ERROR", None, {"field": "instance_id"})
        return _err("VALIDATION_ERROR", "instance_id is missing or malformed", field="instance_id")
    if not isinstance(project_id, str) or not prj_pat.match(project_id):
        _log("VALIDATION_ERROR", instance_id, {"field": "project_id"})
        return _err("VALIDATION_ERROR", "project_id is missing or malformed", field="project_id")
    if not isinstance(name, str) or len(name) < 1:
        _log("VALIDATION_ERROR", instance_id, {"field": "name"})
        return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")

    instances = _load("instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if not inst:
        _log("NOT_FOUND", instance_id)
        return _err("NOT_FOUND", "instance not found", instance_id=instance_id)

    if inst.get("status") != "ready":
        _log("UNAUTHORIZED", instance_id, {"reason": "instance_not_ready"})
        return _err("UNAUTHORIZED", "instance is not ready", instance_id=instance_id, status=inst.get("status"))

    if not inst.get("cap_projects_enabled", False):
        _log("UNAUTHORIZED", instance_id, {"reason": "projects_capability_required"})
        return _err("UNAUTHORIZED", "Enterprise projects capability is not enabled for this instance", instance_id=instance_id)

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    idx = None
    project = None
    for i, p in enumerate(projects):
        if isinstance(p, dict) and p.get("id") == project_id and p.get("instance_id") == instance_id:
            idx = i
            project = p
            break
    if project is None:
        _log("NOT_FOUND", instance_id, {"project_id": project_id})
        return _err("NOT_FOUND", "project not found in instance", instance_id=instance_id, project_id=project_id)

    if project.get("status") == "deleted":
        _log("INVALID_TRANSITION", instance_id, {"from": "deleted"})
        return _err("INVALID_TRANSITION", "cannot update a deleted project", instance_id=instance_id, project_id=project_id)

    # uniqueness: unique(name, instance_id) where status='active'
    for p in projects:
        if not isinstance(p, dict):
            continue
        if p.get("id") == project_id:
            continue
        if p.get("instance_id") == instance_id and p.get("status") == "active" and p.get("name") == name:
            _log("CONFLICT", instance_id, {"reason": "duplicate_name"})
            return _err("CONFLICT", "an active project with this name already exists", instance_id=instance_id, name=name)

    # apply update (idempotent if same name)
    changed = (project.get("name") != name)
    if changed:
        project["name"] = name
    project["updated_at"] = now
    projects[idx] = project
    _save("projects.json", projects)

    _log("OK", instance_id, {"project_id": project_id, "changed": changed})
    return {"project": project, "meta": {"changed": changed}}

def list_users(instance_id, status=None, role=None, search=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0295000" if __import__("os").path.isdir("./environment_mix/0295000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_used=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
                "endpoint": "list-users",
                "instance_id": instance_id,
                "credential_used": credential_used,
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now,
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            return

    # ---- validation ----
    if not isinstance(instance_id, str):
        _log("VALIDATION_ERROR", meta={"field": "instance_id"})
        return _err("VALIDATION_ERROR", "instance_id must be a string", field="instance_id")
    if not re.match(r"^n8n_inst_[0-9A-HJKMNP-TV-Z]{26}$", instance_id):
        _log("VALIDATION_ERROR", meta={"field": "instance_id"})
        return _err("VALIDATION_ERROR", "instance_id has invalid format", field="instance_id")

    if status is not None:
        if not isinstance(status, str) or status not in ("invited", "active", "disabled", "deleted"):
            _log("VALIDATION_ERROR", meta={"field": "status"})
            return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=["invited", "active", "disabled", "deleted"])

    if role is not None:
        if not isinstance(role, str) or role not in ("owner", "admin", "member"):
            _log("VALIDATION_ERROR", meta={"field": "role"})
            return _err("VALIDATION_ERROR", "Invalid role", field="role", allowed=["owner", "admin", "member"])

    if search is not None and not isinstance(search, str):
        _log("VALIDATION_ERROR", meta={"field": "search"})
        return _err("VALIDATION_ERROR", "search must be a string", field="search")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _log("VALIDATION_ERROR", meta={"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
    if limit < 1 or limit > 200:
        _log("VALIDATION_ERROR", meta={"field": "limit"})
        return _err("VALIDATION_ERROR", "limit out of range (1..200)", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR", meta={"field": "cursor"})
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "email", "last_login_at"):
        _log("VALIDATION_ERROR", meta={"field": "sort"})
        return _err("VALIDATION_ERROR", "Invalid sort field", field="sort", allowed=["created_at", "updated_at", "email", "last_login_at"])

    if order is None:
        order = "asc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        _log("VALIDATION_ERROR", meta={"field": "order"})
        return _err("VALIDATION_ERROR", "Invalid order", field="order", allowed=["asc", "desc"])

    # ---- resolve instance / ready status ----
    instances = _load("instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if not inst:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Instance not found", instance_id=instance_id)

    if inst.get("status") != "ready":
        _log("INVALID_TRANSITION", meta={"reason": "instance_not_ready", "instance_status": inst.get("status")})
        return _err("INVALID_TRANSITION", "Instance is not ready", instance_status=inst.get("status"))

    # ---- cursor decode ----
    start = 0
    if cursor:
        try:
            decoded = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            payload = json.loads(decoded)
            if not isinstance(payload, dict) or payload.get("v") != 1 or payload.get("instance_id") != instance_id:
                _log("VALIDATION_ERROR", meta={"field": "cursor"})
                return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
            if payload.get("sort") != sort or payload.get("order") != order:
                _log("VALIDATION_ERROR", meta={"field": "cursor"})
                return _err("VALIDATION_ERROR", "Cursor does not match sort/order", field="cursor")
            start = payload.get("offset", 0)
            if not isinstance(start, int) or start < 0:
                _log("VALIDATION_ERROR", meta={"field": "cursor"})
                return _err("VALIDATION_ERROR", "Invalid cursor offset", field="cursor")
        except (ValueError, json.JSONDecodeError):
            _log("VALIDATION_ERROR", meta={"field": "cursor"})
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    users = _load("users.json")
    if not isinstance(users, list):
        users = []

    rows = []
    q = search.lower() if isinstance(search, str) and search else None
    for u in users:
        if not isinstance(u, dict):
            continue
        if u.get("instance_id") != instance_id:
            continue
        if status is not None and u.get("status") != status:
            continue
        if role is not None and u.get("role") != role:
            continue
        if q:
            email = (u.get("email") or "")
            first = (u.get("first_name") or "")
            last = (u.get("last_name") or "")
            hay = " ".join([str(email), str(first), str(last)]).lower()
            if q not in hay:
                continue
        rows.append(u)

    # sort with stable, deterministic tie-breaker
    reverse = (order == "desc")
    def _key(v):
        x = v.get(sort)
        if sort == "email" and isinstance(x, str):
            x = x.lower()
        return (x is None, x, v.get("id"))

    try:
        rows.sort(key=_key, reverse=reverse)
    except TypeError:
        rows.sort(key=lambda v: (v.get(sort) is None, str(v.get(sort)), v.get("id")), reverse=reverse)

    total = len(rows)
    page = rows[start:start + limit]
    has_more = start + limit < total
    next_cursor = None
    if has_more:
        payload = {"v": 1, "instance_id": instance_id, "sort": sort, "order": order, "offset": start + limit}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order
        }
    }
    _log("OK", meta={"returned": len(page), "total": total, "has_more": has_more})
    return resp

def create_users(instance_id, users, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0295000" if __import__("os").path.isdir("./environment_mix/0295000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _endpoint = "create-users"

    def _log(status, error_code=None, **extra):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{random.randrange(100000,999999)}",
            "endpoint": _endpoint,
            "instance_id": instance_id if isinstance(instance_id, str) else None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now,
            **(extra or {})
        })
        _save("request_logs.json", logs)

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            return None

    def _enforce_limits():
        cfg = _load("service_config.json")
        limit_per_min = None
        quota_per_day = None
        if isinstance(cfg, dict):
            limit_per_min = cfg.get("rate_limit_per_minute")
            quota_per_day = cfg.get("quota_per_day")
        elif isinstance(cfg, list) and cfg and isinstance(cfg[0], dict):
            limit_per_min = cfg[0].get("rate_limit_per_minute")
            quota_per_day = cfg[0].get("quota_per_day")

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = _parse_ts(_now)
        if not now_dt:
            return None

        inst_logs = []
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("instance_id") != instance_id:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts:
                inst_logs.append(ts)

        if isinstance(limit_per_min, int) and limit_per_min > 0:
            cut = now_dt - datetime.timedelta(minutes=1)
            if sum(1 for ts in inst_logs if ts >= cut) >= limit_per_min:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=limit_per_min)

        if isinstance(quota_per_day, int) and quota_per_day > 0:
            cut = now_dt - datetime.timedelta(days=1)
            if sum(1 for ts in inst_logs if ts >= cut) >= quota_per_day:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded", quota_per_day=quota_per_day)

        return None

    def _is_email(e):
        if not isinstance(e, str):
            return False
        e = e.strip()
        if len(e) < 3 or len(e) > 320:
            return False
        return re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", e) is not None

    try:
        if not isinstance(instance_id, str) or not re.match(r"^n8n_inst_[0-9A-HJKMNP-TV-Z]{26}$", instance_id):
            _log("error", "VALIDATION_ERROR", field="instance_id")
            return _err("VALIDATION_ERROR", "instance_id must be a valid n8n instance id.", field="instance_id")
        if not isinstance(users, list):
            _log("error", "VALIDATION_ERROR", field="users")
            return _err("VALIDATION_ERROR", "users must be an array.", field="users")
        if len(users) < 1 or len(users) > 100:
            _log("error", "VALIDATION_ERROR", field="users")
            return _err("VALIDATION_ERROR", "users must contain between 1 and 100 items.", field="users", min=1, max=100)
    except Exception:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid parameters")

    lim_err = _enforce_limits()
    if lim_err:
        _log("error", lim_err["error"]["code"])
        return lim_err

    instances = _load("instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if not inst:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Instance not found", instance_id=instance_id)
    if inst.get("status") != "ready":
        _log("error", "UNAUTHORIZED", instance_status=inst.get("status"))
        return _err("UNAUTHORIZED", "Instance is not ready for operations", instance_status=inst.get("status"))

    existing = _load("users.json")
    if not isinstance(existing, list):
        existing = []

    # validate batch and check conflicts (case-insensitive unique per instance)
    norm_existing = set()
    for u in existing:
        if not isinstance(u, dict):
            continue
        if u.get("instance_id") != instance_id:
            continue
        em = u.get("email")
        if isinstance(em, str) and u.get("status") != "deleted":
            norm_existing.add(em.strip().lower())

    norm_in_batch = set()
    for i, u in enumerate(users):
        if not isinstance(u, dict):
            _log("error", "VALIDATION_ERROR", index=i)
            return _err("VALIDATION_ERROR", "Each user must be an object", index=i)
        if "email" not in u or "role" not in u:
            _log("error", "VALIDATION_ERROR", index=i)
            return _err("VALIDATION_ERROR", "Each user must include email and role", index=i)
        email = u.get("email")
        role = u.get("role")
        if not _is_email(email):
            _log("error", "VALIDATION_ERROR", index=i, field="email")
            return _err("VALIDATION_ERROR", "Invalid email", index=i, field="email")
        if role not in ("owner", "admin", "member"):
            _log("error", "VALIDATION_ERROR", index=i, field="role")
            return _err("VALIDATION_ERROR", "Invalid role", index=i, field="role", allowed=["owner", "admin", "member"])
        emn = email.strip().lower()
        if emn in norm_in_batch:
            _log("error", "CONFLICT", field="email")
            return _err("CONFLICT", "Duplicate email within submitted batch", email=email)
        norm_in_batch.add(emn)
        if emn in norm_existing:
            _log("error", "CONFLICT", field="email")
            return _err("CONFLICT", "User with this email already exists in the instance", email=email, instance_id=instance_id)

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "_" + "".join(random.choice(alphabet) for _ in range(26))

    created = []
    for u in users:
        row = {
            "id": _new_id("n8n_usr"),
            "instance_id": instance_id,
            "n8n_user_id": None,
            "email": u["email"].strip(),
            "first_name": (u.get("first_name").strip() if isinstance(u.get("first_name"), str) and u.get("first_name").strip() else None),
            "last_name": (u.get("last_name").strip() if isinstance(u.get("last_name"), str) and u.get("last_name").strip() else None),
            "role": u["role"],
            "status": "invited",
            "last_login_at": None,
            "created_at": _now,
            "updated_at": _now,
            "deleted_at": None
        }
        existing.append(row)
        created.append(row)

    _save("users.json", existing)
    _log("ok", None, created_count=len(created))
    return {"users": created, "created_count": len(created)}

def get_user(instance_id, user_id=None, email=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0295000" if __import__("os").path.isdir("./environment_mix/0295000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get-user"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status, instance_id_val=None, used_cred=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": None,
            "ts": _now_iso(),
            "endpoint": endpoint,
            "instance_id": instance_id_val,
            "credential": used_cred,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        # lightweight id
        row["id"] = f"req_{len(logs)+1}_{int(time.time()*1000)}"
        logs.append(row)
        _save("request_logs.json", logs)

    def _valid_ulid(pref, s):
        if not isinstance(s, str):
            return False
        return re.match(rf"^{re.escape(pref)}[0-9A-HJKMNP-TV-Z]{{26}}$", s) is not None

    def _valid_email(s):
        if not isinstance(s, str):
            return False
        s2 = s.strip()
        if len(s2) < 3 or len(s2) > 320:
            return False
        # pragmatic email validation
        if "@" not in s2:
            return False
        local, _, domain = s2.rpartition("@")
        if not local or not domain:
            return False
        if ".." in s2:
            return False
        if re.match(r"^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+$", local) is None:
            return False
        if re.match(r"^[A-Za-z0-9.-]+\.[A-Za-z]{2,63}$", domain) is None:
            return False
        return True

    try:
        # Validate inputs
        if not _valid_ulid("n8n_inst_", instance_id):
            _log("error", instance_id_val=instance_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "instance_id is missing or malformed", field="instance_id")

        has_user_id = user_id is not None
        has_email = email is not None
        if (has_user_id and has_email) or (not has_user_id and not has_email):
            _log("error", instance_id_val=instance_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Provide exactly one of user_id or email", fields=["user_id", "email"])

        if has_user_id and not _valid_ulid("n8n_usr_", user_id):
            _log("error", instance_id_val=instance_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "user_id is malformed", field="user_id")

        if has_email and not _valid_email(email):
            _log("error", instance_id_val=instance_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "email is malformed", field="email")

        instances = _load("instances.json")
        if not isinstance(instances, list):
            instances = []
        inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
        if not inst:
            _log("error", instance_id_val=instance_id, error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Instance not found", instance_id=instance_id)

        # Enforce "ready instance" rule (all tools except init-n8n)
        if inst.get("status") != "ready":
            _log("error", instance_id_val=instance_id, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Instance is not ready for operations", instance_status=inst.get("status"))

        users = _load("users.json")
        if not isinstance(users, list):
            users = []

        match = None
        if has_user_id:
            match = next((u for u in users if isinstance(u, dict) and u.get("id") == user_id and u.get("instance_id") == instance_id), None)
        else:
            target = email.strip().lower()
            # unique(lower(email), instance_id) per schema; still search defensively
            for u in users:
                if not isinstance(u, dict):
                    continue
                if u.get("instance_id") != instance_id:
                    continue
                em = u.get("email")
                if isinstance(em, str) and em.strip().lower() == target:
                    match = u
                    break

        if not match:
            _log("error", instance_id_val=instance_id, error_code="NOT_FOUND")
            return _err("NOT_FOUND", "User not found in instance", instance_id=instance_id)

        # Business rule: deleted users exist but are still retrievable by id/email unless caller blocks (not specified).
        # Return as-is.
        _log("ok", instance_id_val=instance_id)
        return {"user": match}
    except Exception as e:
        _log("error", instance_id_val=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def delete_user(instance_id, user_id, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0295000" if __import__("os").path.isdir("./environment_mix/0295000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _endpoint = "delete-user"
    _now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _new_req_id():
        return f"req_{int(time.time()*1000)}_{random.randrange(100000,999999)}"

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        s = ts.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status, error_code=None, **extra):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_req_id(),
            "endpoint": _endpoint,
            "instance_id": instance_id if isinstance(instance_id, str) else None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now,
            **(extra or {})
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        cfg = _load("service_config.json")
        limit_per_min = None
        quota_per_day = None
        if isinstance(cfg, dict):
            limit_per_min = cfg.get("rate_limit_per_minute") or cfg.get("requests_per_minute")
            quota_per_day = cfg.get("quota_per_day") or cfg.get("requests_per_day")
        elif isinstance(cfg, list) and cfg and isinstance(cfg[0], dict):
            limit_per_min = cfg[0].get("rate_limit_per_minute") or cfg[0].get("requests_per_minute")
            quota_per_day = cfg[0].get("quota_per_day") or cfg[0].get("requests_per_day")
        if limit_per_min is None and quota_per_day is None:
            return None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = _parse_ts(_now)
        if now_dt is None:
            return None

        inst_logs = []
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("instance_id") != instance_id:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is not None:
                inst_logs.append(ts)

        if limit_per_min is not None:
            try:
                rpm = int(limit_per_min)
                if rpm >= 0:
                    cutoff = now_dt - datetime.timedelta(seconds=60)
                    if sum(1 for ts in inst_logs if ts >= cutoff) >= rpm:
                        return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=rpm, instance_id=instance_id)
            except Exception:
                pass

        if quota_per_day is not None:
            try:
                qd = int(quota_per_day)
                if qd >= 0:
                    cutoff = now_dt - datetime.timedelta(days=1)
                    if sum(1 for ts in inst_logs if ts >= cutoff) >= qd:
                        return _err("QUOTA_EXCEEDED", "Daily quota exceeded", quota_per_day=qd, instance_id=instance_id)
            except Exception:
                pass
        return None

    if not isinstance(instance_id, str) or not re.match(r"^n8n_inst_[0-9A-HJKMNP-TV-Z]{26}$", instance_id):
        out = _err("VALIDATION_ERROR", "Invalid instance_id")
        _log("error", out["error"]["code"])
        return out
    if not isinstance(user_id, str) or not re.match(r"^n8n_usr_[0-9A-HJKMNP-TV-Z]{26}$", user_id):
        out = _err("VALIDATION_ERROR", "Invalid user_id")
        _log("error", out["error"]["code"])
        return out

    limited = _enforce_limits()
    if limited:
        _log("error", limited["error"]["code"])
        return limited

    instances = _load("instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if not inst:
        out = _err("NOT_FOUND", "Instance not found", instance_id=instance_id)
        _log("error", out["error"]["code"])
        return out
    if inst.get("status") != "ready":
        out = _err("INVALID_TRANSITION", "Instance is not ready for user operations", instance_status=inst.get("status"), required_status="ready", instance_id=instance_id)
        _log("error", out["error"]["code"])
        return out

    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    idx = None
    u = None
    for i, r in enumerate(users):
        if isinstance(r, dict) and r.get("id") == user_id and r.get("instance_id") == instance_id:
            idx = i
            u = r
            break
    if u is None:
        out = _err("NOT_FOUND", "User not found in this instance", instance_id=instance_id, user_id=user_id)
        _log("error", out["error"]["code"])
        return out

    # Common n8n rule: cannot delete the owner if it's the instance owner_user_id
    if inst.get("owner_user_id") == user_id and u.get("status") != "deleted":
        out = _err("CONFLICT", "Instance owner user cannot be deleted", user_id=user_id, instance_id=instance_id)
        _log("error", out["error"]["code"])
        return out

    # Idempotent
    if u.get("status") == "deleted":
        _log("ok")
        return {"user": u, "changed": False}

    # Lifecycle transitions allow to 'deleted' from invited/active/disabled
    if u.get("status") not in ("invited", "active", "disabled"):
        out = _err("INVALID_TRANSITION", "Cannot delete user from current status", from_status=u.get("status"), to_status="deleted", user_id=user_id)
        _log("error", out["error"]["code"])
        return out

    u2 = dict(u)
    u2["status"] = "deleted"
    u2["deleted_at"] = _now
    u2["updated_at"] = _now
    users[idx] = u2
    _save("users.json", users)

    _log("ok")
    return {"user": u2, "changed": True}

def list_variables(instance_id, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0295000" if __import__("os").path.isdir("./environment_mix/0295000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- helpers ----
    def _log(status, used_instance_id, message=None, **extra):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "ts": now,
            "endpoint": "list-variables",
            "instance_id": used_instance_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if message is not None:
            row["message"] = message
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _is_str(x): return isinstance(x, str)
    def _is_int(x): return isinstance(x, int) and not isinstance(x, bool)

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not _is_str(cur) or cur == "":
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        s = cur
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        try:
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        if not isinstance(obj, dict):
            return _err("VALIDATION_ERROR", "cursor is invalid")
        return obj

    # ---- validate inputs ----
    if not _is_str(instance_id) or not instance_id:
        _log("error", None, "invalid instance_id")
        return _err("VALIDATION_ERROR", "instance_id must be a non-empty string")

    if limit is None:
        limit = 50
    if not _is_int(limit) or limit < 1 or limit > 250:
        _log("error", instance_id, "invalid limit")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 250")

    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "updated_at", "name"):
        _log("error", instance_id, "invalid sort")
        return _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, name")

    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        _log("error", instance_id, "invalid order")
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc")

    cur_obj = _decode_cursor(cursor)
    if isinstance(cur_obj, dict) and "error" in cur_obj:
        _log("error", instance_id, "invalid cursor")
        return cur_obj

    if cur_obj is not None:
        # Ensure cursor matches query shape for stable paging
        if cur_obj.get("instance_id") != instance_id or cur_obj.get("sort") != sort or cur_obj.get("order") != order:
            _log("error", instance_id, "cursor query mismatch")
            return _err("VALIDATION_ERROR", "cursor does not match instance_id/sort/order")

    # ---- resolve instance and capability/auth ----
    instances = _load("instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if inst is None:
        _log("error", instance_id, "instance not found")
        return _err("NOT_FOUND", "instance not found", instance_id=instance_id)

    # Must be ready for all operations except init-n8n (not this tool)
    if inst.get("status") != "ready":
        _log("error", instance_id, "instance not ready")
        return _err("UNAUTHORIZED", "instance is not ready for operations", instance_status=inst.get("status"))

    if not bool(inst.get("cap_variables_enabled")):
        _log("error", instance_id, "variables capability not enabled")
        return _err("UNAUTHORIZED", "variables capability is not enabled for this instance")

    # ---- rate limiting/quota (observable dynamics) ----
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    # Simple per-instance rate limit: 120 requests/minute
    one_min_ago = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
    recent = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("instance_id") != instance_id:
            continue
        ts = r.get("ts")
        if isinstance(ts, str) and ts >= one_min_ago:
            recent += 1
    if recent >= 120:
        _log("error", instance_id, "rate limit exceeded")
        return _err("RATE_LIMIT", "rate limit exceeded", limit_per_minute=120)

    # ---- load variables ----
    ops = _load("ops_and_metadata.json")
    if not isinstance(ops, list):
        ops = []

    variables = []
    for r in ops:
        if not isinstance(r, dict):
            continue
        if r.get("instance_id") != instance_id:
            continue
        if r.get("record_type") != "variable":
            continue
        if r.get("status") == "deleted":
            continue
        # enforce constraint: name is not null
        if r.get("name") is None:
            continue
        variables.append(r)

    # ---- sorting ----
    def _sort_key(row):
        v = row.get(sort)
        if sort == "name":
            return (str(v).casefold() if v is not None else "", row.get("id", ""))
        # created_at/updated_at are ISO strings; lexical works if consistent
        return (str(v) if v is not None else "", row.get("id", ""))

    reverse = (order == "desc")
    variables.sort(key=_sort_key, reverse=reverse)

    # ---- apply cursor ----
    start_index = 0
    if cur_obj is not None:
        after = cur_obj.get("after")
        if not isinstance(after, dict):
            _log("error", instance_id, "cursor missing after")
            return _err("VALIDATION_ERROR", "cursor is invalid")
        after_id = after.get("id")
        after_sortval = after.get("v")
        if not _is_str(after_id):
            _log("error", instance_id, "cursor invalid after.id")
            return _err("VALIDATION_ERROR", "cursor is invalid")

        def _cmp_sortval(row):
            rv = row.get(sort)
            if sort == "name":
                return str(rv).casefold() if rv is not None else ""
            return str(rv) if rv is not None else ""

        # Find first element strictly after the cursor marker in the current ordering
        found_pos = None
        for i, row in enumerate(variables):
            if row.get("id") == after_id and _cmp_sortval(row) == (str(after_sortval).casefold() if sort == "name" else str(after_sortval)):
                found_pos = i
                break
        if found_pos is None:
            # Cursor doesn't correspond to current result set; treat as validation error
            _log("error", instance_id, "cursor not found in result set")
            return _err("VALIDATION_ERROR", "cursor is invalid or expired")
        start_index = found_pos + 1

    page = variables[start_index:start_index + limit]
    has_more = (start_index + limit) < len(variables)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_v = last.get(sort)
        if sort == "name":
            last_v = (str(last_v).casefold() if last_v is not None else "")
        else:
            last_v = (str(last_v) if last_v is not None else "")
        next_cursor = _encode_cursor({
            "instance_id": instance_id,
            "sort": sort,
            "order": order,
            "after": {"id": last.get("id"), "v": last_v}
        })

    # ---- response envelope ----
    # Return only variable-like fields (but keep source row shape; do not fabricate)
    resp = {
        "data": page,
        "meta": {
            "total": len(variables),
            "limit": limit,
            "sort": sort,
            "order": order,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }
    _log("ok", instance_id)
    return resp

def create_variable(instance_id, name, value, **_extra):
    import json, os, datetime, time, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0295000" if __import__("os").path.isdir("./environment_mix/0295000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _endpoint = "create-variable"

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            return None

    def _log(status, error_code=None, **extra):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{random.randrange(100000,999999)}",
            "endpoint": _endpoint,
            "instance_id": instance_id if isinstance(instance_id, str) else None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now,
            **(extra or {})
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        cfg = _load("service_config.json")
        limit_per_min = None
        quota_per_day = None
        if isinstance(cfg, dict):
            limit_per_min = cfg.get("rate_limit_per_minute")
            quota_per_day = cfg.get("quota_per_day")
        elif isinstance(cfg, list) and cfg and isinstance(cfg[0], dict):
            limit_per_min = cfg[0].get("rate_limit_per_minute")
            quota_per_day = cfg[0].get("quota_per_day")

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now_dt = _parse_ts(_now)
        if not now_dt:
            return None

        inst_logs = []
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("instance_id") != instance_id:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is not None:
                inst_logs.append(ts)

        if isinstance(limit_per_min, int) and limit_per_min > 0:
            cutoff = now_dt - datetime.timedelta(seconds=60)
            used = sum(1 for ts in inst_logs if ts >= cutoff)
            if used >= limit_per_min:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=limit_per_min)

        if isinstance(quota_per_day, int) and quota_per_day > 0:
            day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
            used = sum(1 for ts in inst_logs if ts >= day_start)
            if used >= quota_per_day:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded", quota_per_day=quota_per_day)

        return None

    try:
        if not isinstance(instance_id, str) or not instance_id.strip():
            lim_err = _enforce_limits()
            if lim_err:
                _log("error", lim_err["error"]["code"])
                return lim_err
            _log("error", "VALIDATION_ERROR", field="instance_id")
            return _err("VALIDATION_ERROR", "instance_id is required and must be a string", field="instance_id")
        if not isinstance(name, str) or not name.strip():
            lim_err = _enforce_limits()
            if lim_err:
                _log("error", lim_err["error"]["code"])
                return lim_err
            _log("error", "VALIDATION_ERROR", field="name")
            return _err("VALIDATION_ERROR", "name is required and must be a non-empty string", field="name")
        if not isinstance(value, str):
            lim_err = _enforce_limits()
            if lim_err:
                _log("error", lim_err["error"]["code"])
                return lim_err
            _log("error", "VALIDATION_ERROR", field="value")
            return _err("VALIDATION_ERROR", "value is required and must be a string", field="value")
    except Exception:
        lim_err = _enforce_limits()
        if lim_err:
            _log("error", lim_err["error"]["code"])
            return lim_err
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid parameters")

    lim_err = _enforce_limits()
    if lim_err:
        _log("error", lim_err["error"]["code"])
        return lim_err

    nm = name.strip()
    if len(nm) > 255 or re.search(r"[\x00-\x1f\x7f]", nm):
        _log("error", "VALIDATION_ERROR", field="name")
        return _err("VALIDATION_ERROR", "name is invalid", field="name")

    instances = _load("instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if not inst:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Instance not found", instance_id=instance_id)
    if inst.get("status") != "ready":
        _log("error", "UNAUTHORIZED", instance_status=inst.get("status"))
        return _err("UNAUTHORIZED", "Instance is not ready for operations", instance_status=inst.get("status"))
    if not inst.get("cap_variables_enabled", False):
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Enterprise variable management is not enabled for this instance", instance_id=instance_id)

    ops = _load("ops_and_metadata.json")
    if not isinstance(ops, list):
        ops = []

    # unique(instance_id, record_type, name) where record_type='variable' and status!='deleted'
    for r in ops:
        if not isinstance(r, dict):
            continue
        if r.get("instance_id") != instance_id:
            continue
        if r.get("record_type") != "variable":
            continue
        if r.get("status") == "deleted":
            continue
        if (r.get("name") or "") == nm:
            _log("error", "CONFLICT")
            return _err("CONFLICT", "Variable name already exists in this instance", name=nm)

    alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _gen_id():
        return "n8n_op_" + "".join(random.choice(alphabet) for _ in range(26))
    new_id = _gen_id()
    existing_ids = {r.get("id") for r in ops if isinstance(r, dict)}
    tries = 0
    while new_id in existing_ids and tries < 10:
        new_id = _gen_id()
        tries += 1
    if new_id in existing_ids:
