        logs.append({
            "id": _new_req_id(),
            "endpoint": _endpoint,
            "instance_id": instance_id if isinstance(instance_id, str) else None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now,
            **(extra or {})
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        cfg = _load("service_config.json")
        limit_per_min = None
        quota_per_day = None
        if isinstance(cfg, dict):
            limit_per_min = cfg.get("rate_limit_per_minute") or cfg.get("requests_per_minute")
            quota_per_day = cfg.get("quota_per_day") or cfg.get("requests_per_day")
        elif isinstance(cfg, list) and cfg and isinstance(cfg[0], dict):
            limit_per_min = cfg[0].get("rate_limit_per_minute") or cfg[0].get("requests_per_minute")
            quota_per_day = cfg[0].get("quota_per_day") or cfg[0].get("requests_per_day")
        if limit_per_min is None and quota_per_day is None:
            return None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = _parse_ts(_now)
        if now_dt is None:
            return None

        inst_logs = []
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("instance_id") != instance_id:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is not None:
                inst_logs.append(ts)

        if limit_per_min is not None:
            try:
                rpm = int(limit_per_min)
                if rpm >= 0:
                    cutoff = now_dt - datetime.timedelta(seconds=60)
                    if sum(1 for ts in inst_logs if ts >= cutoff) >= rpm:
                        return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=rpm, instance_id=instance_id)
            except Exception:
                pass

        if quota_per_day is not None:
            try:
                qd = int(quota_per_day)
                if qd >= 0:
                    cutoff = now_dt - datetime.timedelta(days=1)
                    if sum(1 for ts in inst_logs if ts >= cutoff) >= qd:
                        return _err("QUOTA_EXCEEDED", "Daily quota exceeded", quota_per_day=qd, instance_id=instance_id)
            except Exception:
                pass
        return None

    if not isinstance(instance_id, str) or not instance_id.startswith("n8n_inst_"):
        out = _err("VALIDATION_ERROR", "Invalid instance_id")
        _log("error", out["error"]["code"])
        return out
    if not isinstance(type_name, str) or not type_name.strip():
        out = _err("VALIDATION_ERROR", "type_name must be a non-empty string")
        _log("error", out["error"]["code"])
        return out

    limited = _enforce_limits()
    if limited:
        _log("error", limited["error"]["code"])
        return limited

    instances = _load("instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if not inst:
        out = _err("NOT_FOUND", "Instance not found", instance_id=instance_id)
        _log("error", out["error"]["code"])
        return out
    if inst.get("status") != "ready":
        out = _err("INVALID_TRANSITION", "Instance is not ready for credential schema operations", instance_status=inst.get("status"), required_status="ready", instance_id=instance_id)
        _log("error", out["error"]["code"])
        return out

    ops = _load("ops_and_metadata.json")
    if not isinstance(ops, list):
        ops = []
    tn = type_name.strip()

    schema = next((r for r in ops if isinstance(r, dict) and r.get("instance_id") == instance_id and r.get("record_type") == "credential_schema" and r.get("type_name") == tn and r.get("status") != "deleted" and r.get("data") is not None), None)
    if schema:
        _log("ok")
        return {"credential_schema": schema}

    # If not cached, fall back to any known schema in store (best-effort offline behavior), then cache to instance.
    any_schema = next((r for r in ops if isinstance(r, dict) and r.get("record_type") == "credential_schema" and r.get("type_name") == tn and r.get("data") is not None and r.get("status") != "deleted"), None)
    if not any_schema:
        out = _err("NOT_FOUND", "Credential schema not found for requested type_name", type_name=tn, instance_id=instance_id)
        _log("error", out["error"]["code"])
        return out

    # Cache a copy for this instance (idempotent if called concurrently; still ok)
    def _new_ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(26))

    cached = dict(any_schema)
    cached["id"] = _new_ulid_like("n8n_op_")
    cached["instance_id"] = instance_id
    cached["created_at"] = _now
    cached["updated_at"] = _now
    cached["deleted_at"] = None
    cached["status"] = "active"
    cached["ref_id"] = cached.get("ref_id")
    cached["workflow_id"] = None
    cached["tag_id"] = None
    cached["project_id"] = None
    cached["user_id"] = None
    cached["name"] = None  # schema doesn't use name; type_name identifies
    ops.append(cached)
    _save("ops_and_metadata.json", ops)

    _log("ok", cached=True)
    return {"credential_schema": cached}

def list_executions(instance_id, workflow_id=None, status=None, started_after=None, started_before=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0295000" if __import__("os").path.isdir("./environment_mix/0295000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list-executions"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return "TYPE", None
        try:
            # Accept trailing Z
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return None, dt.astimezone(datetime.timezone.utc)
        except Exception:
            return "FORMAT", None

    def _make_cursor(payload_obj):
        raw = json.dumps(payload_obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _read_cursor(cur):
        if cur is None:
            return None, None
        if not isinstance(cur, str) or not cur:
            return "INVALID", None
        try:
            pad = "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return "INVALID", None
            return None, obj
        except Exception:
            return "INVALID", None

    def _stable_hash(filters_obj):
        # used to validate cursor belongs to same filter set
        b = json.dumps(filters_obj, separators=(",", ":"), sort_keys=True, ensure_ascii=False).encode("utf-8")
        return hashlib.sha256(b).hexdigest()

    # ---- ambient auth resolution (must find a ready instance that satisfies request) ----
    instances = _load("instances.json")
    inst = None
    if isinstance(instance_id, str):
        for r in instances:
            if r.get("id") == instance_id:
                inst = r
                break
    # request logging collection
    reqlog = _load("request_log.json")
    if not isinstance(reqlog, list):
        reqlog = []

    def _log_and_return(resp, status_code):
        latency_ms = int((time.time() - t0) * 1000)
        reqlog.append({
            "id": f"req_{int(time.time()*1000)}_{len(reqlog)+1}",
            "endpoint": endpoint,
            "instance_id": instance_id if isinstance(instance_id, str) else None,
            "status": status_code,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        })
        _save("request_log.json", reqlog)
        return resp

    if inst is None:
        return _log_and_return(_err("NOT_FOUND", "Instance not found.", instance_id=instance_id), 404)
    if inst.get("status") != "ready":
        return _log_and_return(_err("UNAUTHORIZED", "Instance is not ready for operations.", instance_status=inst.get("status")), 401)

    # ---- validate inputs ----
    if workflow_id is not None and not isinstance(workflow_id, str):
        return _log_and_return(_err("VALIDATION_ERROR", "workflow_id must be a string."), 400)

    allowed_status = {"queued", "running", "succeeded", "failed"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid status filter.", allowed=sorted(list(allowed_status))), 400)

    e, dt_after = _parse_dt(started_after, "started_after")
    if e == "TYPE":
        return _log_and_return(_err("VALIDATION_ERROR", "started_after must be an ISO 8601 string."), 400)
    if e == "FORMAT":
        return _log_and_return(_err("VALIDATION_ERROR", "Invalid started_after timestamp."), 400)

    e, dt_before = _parse_dt(started_before, "started_before")
    if e == "TYPE":
        return _log_and_return(_err("VALIDATION_ERROR", "started_before must be an ISO 8601 string."), 400)
    if e == "FORMAT":
        return _log_and_return(_err("VALIDATION_ERROR", "Invalid started_before timestamp."), 400)

    if dt_after and dt_before and dt_before < dt_after:
        return _log_and_return(_err("VALIDATION_ERROR", "started_before must be >= started_after."), 400)

    if limit is None:
        limit_i = 50
    else:
        if not isinstance(limit, int):
            return _log_and_return(_err("VALIDATION_ERROR", "limit must be an integer."), 400)
        if limit < 1 or limit > 250:
            return _log_and_return(_err("VALIDATION_ERROR", "limit must be between 1 and 250."), 400)
        limit_i = limit

    allowed_sort = {"started_at", "finished_at", "created_at"}
    sort_f = sort or "started_at"
    if not isinstance(sort_f, str) or sort_f not in allowed_sort:
        return _log_and_return(_err("VALIDATION_ERROR", "Invalid sort field.", allowed=sorted(list(allowed_sort))), 400)

    allowed_order = {"asc", "desc"}
    order_v = order or "desc"
    if not isinstance(order_v, str) or order_v not in allowed_order:
        return _log_and_return(_err("VALIDATION_ERROR", "Invalid order.", allowed=sorted(list(allowed_order))), 400)

    # workflow existence and instance scoping
    workflows = _load("workflows.json")
    wf_row = None
    if workflow_id is not None:
        for w in workflows:
            if w.get("id") == workflow_id and w.get("instance_id") == inst.get("id"):
                wf_row = w
                break
        if wf_row is None:
            return _log_and_return(_err("NOT_FOUND", "Workflow not found in this instance.", workflow_id=workflow_id), 404)
        # list-executions excludes deleted by default but for workflows business rule states same instance; deleted workflow can still have executions;
        # we allow listing executions even if workflow record is deleted? vendor unclear; keep strict: only workflows in same instance, regardless of status.
        # (wf_row found already)

    # ---- cursor validation ----
    filters_obj = {
        "instance_id": inst.get("id"),
        "workflow_id": workflow_id,
        "status": status,
        "started_after": dt_after.isoformat() if dt_after else None,
        "started_before": dt_before.isoformat() if dt_before else None,
        "sort": sort_f,
        "order": order_v,
    }
    fhash = _stable_hash(filters_obj)

    offset = 0
    if cursor is not None:
        ce, cobj = _read_cursor(cursor)
        if ce:
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid cursor."), 400)
        if cobj.get("v") != 1 or cobj.get("t") != "exec":
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid cursor."), 400)
        if cobj.get("fh") != fhash:
            return _log_and_return(_err("VALIDATION_ERROR", "Cursor does not match the current query."), 400)
        off = cobj.get("o")
        if not isinstance(off, int) or off < 0:
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid cursor."), 400)
        offset = off

    # ---- fetch + filter ----
    ops = _load("ops_and_metadata.json")
    if not isinstance(ops, list):
        ops = []

    # enforce execution record type and status domain
    rows = []
    inst_id = inst.get("id")
    for r in ops:
        if r.get("instance_id") != inst_id:
            continue
        if r.get("record_type") != "execution":
            continue
        # exclude deleted by default
        if r.get("status") == "deleted" or r.get("deleted_at") is not None:
            continue
        # execution must have workflow_id and belong to same instance workflow
        wfid = r.get("workflow_id")
        if not wfid:
            continue
        if workflow_id is not None and wfid != workflow_id:
            continue
        if status is not None and r.get("status") != status:
            continue

        # started_at filtering: if missing started_at, treat as not matching when filter present
        s_at = r.get("started_at")
        if (dt_after or dt_before):
            if not isinstance(s_at, str):
                continue
            pe, sdt = _parse_dt(s_at, "started_at_row")
            if pe:
                continue
            if dt_after and sdt < dt_after:
                continue
            if dt_before and sdt > dt_before:
                continue

        # Ensure the referenced workflow belongs to same instance
        # For performance, only check when needed: build index lazily
        rows.append(r)

    # Build workflow index for instance scoping check
    wf_index = {w.get("id"): w for w in workflows if w.get("instance_id") == inst_id}
    scoped_rows = []
    for r in rows:
        if r.get("workflow_id") in wf_index:
            scoped_rows.append(r)
    rows = scoped_rows

    # ---- sort ----
    def _key_dt(val):
        if not isinstance(val, str):
            return None
        pe, dtv = _parse_dt(val, "k")
        if pe:
            return None
        return dtv

    def _sort_key(r):
        v = r.get(sort_f)
        dtv = _key_dt(v)
        # place None at end for desc and asc consistently by using tuple
        return (dtv is None, dtv)

    reverse = (order_v == "desc")
    try:
        rows.sort(key=_sort_key, reverse=reverse)
    except Exception:
        return _log_and_return(_err("VALIDATION_ERROR", "Unable to sort by requested field."), 400)

    total = len(rows)
    page = rows[offset: offset + limit_i]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _make_cursor({"v": 1, "t": "exec", "fh": fhash, "o": next_offset}) if has_more else None

    resp = {
        "object": "list",
        "data": page,
        "instance_id": inst_id,
        "total": total,
        "limit": limit_i,
        "cursor": next_cursor,
        "has_more": has_more,
        "sort": sort_f,
        "order": order_v,
    }
    return _log_and_return(resp, 200)

