            "instance_id": instance_id if isinstance(instance_id, str) else None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now,
            **(extra or {})
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        cfg = _load("service_config.json")
        limit_per_min = None
        quota_per_day = None
        if isinstance(cfg, dict):
            limit_per_min = cfg.get("rate_limit_per_minute") or cfg.get("requests_per_minute")
            quota_per_day = cfg.get("quota_per_day") or cfg.get("requests_per_day")
        elif isinstance(cfg, list) and cfg and isinstance(cfg[0], dict):
            limit_per_min = cfg[0].get("rate_limit_per_minute") or cfg[0].get("requests_per_minute")
            quota_per_day = cfg[0].get("quota_per_day") or cfg[0].get("requests_per_day")
        if limit_per_min is None and quota_per_day is None:
            return None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = _parse_ts(_now)
        if now_dt is None:
            return None

        inst_logs = []
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("instance_id") != instance_id:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is not None:
                inst_logs.append(ts)

        if limit_per_min is not None:
            try:
                rpm = int(limit_per_min)
                if rpm >= 0:
                    cutoff = now_dt - datetime.timedelta(seconds=60)
                    if sum(1 for ts in inst_logs if ts >= cutoff) >= rpm:
                        return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=rpm, instance_id=instance_id)
            except Exception:
                pass

        if quota_per_day is not None:
            try:
                qd = int(quota_per_day)
                if qd >= 0:
                    cutoff = now_dt - datetime.timedelta(days=1)
                    if sum(1 for ts in inst_logs if ts >= cutoff) >= qd:
                        return _err("QUOTA_EXCEEDED", "Daily quota exceeded", quota_per_day=qd, instance_id=instance_id)
            except Exception:
                pass
        return None

    if not isinstance(instance_id, str) or not instance_id.startswith("n8n_inst_"):
        out = _err("VALIDATION_ERROR", "Invalid instance_id")
        _log("error", out["error"]["code"])
        return out
    if not isinstance(execution_id, str) or not execution_id:
        out = _err("VALIDATION_ERROR", "Invalid execution_id")
        _log("error", out["error"]["code"])
        return out

    limited = _enforce_limits()
    if limited:
        _log("error", limited["error"]["code"])
        return limited

    instances = _load("instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if not inst:
        out = _err("NOT_FOUND", "Instance not found", instance_id=instance_id)
        _log("error", out["error"]["code"])
        return out
    if inst.get("status") != "ready":
        out = _err("INVALID_TRANSITION", "Instance is not ready for execution operations", instance_status=inst.get("status"), required_status="ready", instance_id=instance_id)
        _log("error", out["error"]["code"])
        return out

    ops = _load("ops_and_metadata.json")
    if not isinstance(ops, list):
        ops = []
    idx = None
    exe = None
    for i, r in enumerate(ops):
        if isinstance(r, dict) and r.get("id") == execution_id and r.get("instance_id") == instance_id and r.get("record_type") == "execution":
            idx = i
            exe = r
            break
    if exe is None:
        out = _err("NOT_FOUND", "Execution not found in this instance", instance_id=instance_id, execution_id=execution_id)
        _log("error", out["error"]["code"])
        return out

    # Idempotent
    if exe.get("status") == "deleted":
        _log("ok")
        return {"execution": exe, "changed": False}

    # Transition validation: allow delete from queued/running/succeeded/failed per lifecycle
    if exe.get("status") not in ("queued", "running", "succeeded", "failed"):
        out = _err("INVALID_TRANSITION", "Cannot delete execution from current status", from_status=exe.get("status"), to_status="deleted", execution_id=execution_id)
        _log("error", out["error"]["code"])
        return out

    exe2 = dict(exe)
    exe2["status"] = "deleted"
    exe2["deleted_at"] = _now
    exe2["updated_at"] = _now
    ops[idx] = exe2
    _save("ops_and_metadata.json", ops)

    _log("ok")
    return {"execution": exe2, "changed": True}

def create_tag(instance_id, name, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0295000" if __import__("os").path.isdir("./environment_mix/0295000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create-tag"
    credential_used = None

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _record_request(status_code, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "instance_id": instance_id if isinstance(instance_id, str) else None,
            "credential_id": credential_used,
            "status_code": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _is_ulid_like(s):
        return isinstance(s, str) and len(s) >= 10

    def _norm_tag(s):
        # Case-insensitive uniqueness with trimmed whitespace
        return re.sub(r"\s+", " ", s.strip()).lower()

    # Quota / rate limiting (simple observable dynamics via request_logs)
    # - Rate limit: 30 create-tag calls per minute per instance
    # - Quota: 500 tags per instance (active/non-deleted)
    now = datetime.datetime.utcnow()
    logs = _load("request_logs.json")
    if isinstance(logs, list):
        one_min_ago = (now - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
        recent = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            if r.get("instance_id") != instance_id:
                continue
            ts = r.get("ts")
            if isinstance(ts, str) and ts >= one_min_ago:
                recent += 1
        if recent >= 30:
            _record_request(429, "RATE_LIMIT")
            return _err("RATE_LIMIT", "rate limit exceeded for create-tag", limit_per_minute=30)

    # Validation
    if not _is_ulid_like(instance_id) or not instance_id.startswith("n8n_inst_"):
        _record_request(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_id is malformed")
    if not isinstance(name, str):
        _record_request(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be a string")
    if name.strip() == "":
        _record_request(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must not be blank")

    instances = _load("instances.json")
    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if not inst:
        _record_request(404, "NOT_FOUND")
        return _err("NOT_FOUND", "instance not found")
    if inst.get("status") != "ready":
        _record_request(409, "CONFLICT")
        return _err("CONFLICT", "instance is not ready", instance_status=inst.get("status"))

    ops = _load("ops_and_metadata.json")
    if not isinstance(ops, list):
        ops = []

    # Quota: max 500 non-deleted tags per instance
    active_tags = [
        r for r in ops
        if isinstance(r, dict)
        and r.get("instance_id") == instance_id
        and r.get("record_type") == "tag"
        and r.get("status") != "deleted"
    ]
    if len(active_tags) >= 500:
        _record_request(429, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "tag quota exceeded for instance", quota=500)

    normalized = _norm_tag(name)
    # Enforce unique tag name per instance (case-insensitive) among non-deleted
    for r in active_tags:
        existing_name = r.get("name")
        if isinstance(existing_name, str) and _norm_tag(existing_name) == normalized:
            _record_request(409, "CONFLICT")
            return _err("CONFLICT", "tag with same name already exists", existing_tag_id=r.get("id"))

    # Create
    ts = _now()
    new_id = f"meta_tag_{int(time.time()*1000)}_{os.getpid()}_{len(ops)+1}"
    row = {
        "id": new_id,
        "instance_id": instance_id,
        "record_type": "tag",
        "status": "active",
        "ref_id": None,
        "workflow_id": None,
        "tag_id": None,
        "project_id": None,
        "user_id": None,
        "name": name.strip(),
        "type_name": None,
        "data": None,
        "started_at": None,
        "finished_at": None,
        "created_at": ts,
        "updated_at": ts,
        "deleted_at": None,
    }

    ops.append(row)
    _save("ops_and_metadata.json", ops)
    _record_request(201, None)
    return {"tag": row}

def list_tags(instance_id, limit=None, cursor=None, sort=None, order=None, q=None, **_extra):
    import json, os, datetime, time, base64, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0295000" if __import__("os").path.isdir("./environment_mix/0295000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list-tags"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _make_cursor(payload_obj):
        raw = json.dumps(payload_obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _read_cursor(cur):
        if cur is None:
            return None, None
        if not isinstance(cur, str) or not cur:
            return "INVALID", None
        try:
            pad = "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return "INVALID", None
            return None, obj
        except Exception:
            return "INVALID", None

    def _stable_hash(filters_obj):
        b = json.dumps(filters_obj, separators=(",", ":"), sort_keys=True, ensure_ascii=False).encode("utf-8")
        return hashlib.sha256(b).hexdigest()

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    # request logging
    reqlog = _load("request_log.json")
    if not isinstance(reqlog, list):
        reqlog = []

    def _log_and_return(resp, status_code):
        latency_ms = int((time.time() - t0) * 1000)
        reqlog.append({
            "id": f"req_{int(time.time()*1000)}_{len(reqlog)+1}",
            "endpoint": endpoint,
            "instance_id": instance_id if isinstance(instance_id, str) else None,
            "status": status_code,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        })
        _save("request_log.json", reqlog)
        return resp

    # ---- auth/instance readiness ----
    instances = _load("instances.json")
    inst = None
    if isinstance(instance_id, str):
        for r in instances:
            if r.get("id") == instance_id:
                inst = r
                break
    if inst is None:
        return _log_and_return(_err("NOT_FOUND", "Instance not found.", instance_id=instance_id), 404)
    if inst.get("status") != "ready":
        return _log_and_return(_err("UNAUTHORIZED", "Instance is not ready for operations.", instance_status=inst.get("status")), 401)

    # permission model not represented in datastore; with ambient auth and no per-user context, allow when instance is ready.

    # ---- validate inputs ----
    if limit is None:
        limit_i = 50
    else:
        if not isinstance(limit, int):
            return _log_and_return(_err("VALIDATION_ERROR", "limit must be an integer."), 400)
        if limit < 1 or limit > 250:
            return _log_and_return(_err("VALIDATION_ERROR", "limit must be between 1 and 250."), 400)
        limit_i = limit

    allowed_sort = {"created_at", "updated_at", "name"}
    sort_f = sort or "name"
    if not isinstance(sort_f, str) or sort_f not in allowed_sort:
        return _log_and_return(_err("VALIDATION_ERROR", "Invalid sort field.", allowed=sorted(list(allowed_sort))), 400)

    allowed_order = {"asc", "desc"}
    order_v = order or "asc"
    if not isinstance(order_v, str) or order_v not in allowed_order:
        return _log_and_return(_err("VALIDATION_ERROR", "Invalid order.", allowed=sorted(list(allowed_order))), 400)

    if q is not None and not isinstance(q, str):
        return _log_and_return(_err("VALIDATION_ERROR", "q must be a string."), 400)
    q_norm = (q or "").strip().lower()

    # ---- cursor validation ----
    filters_obj = {
        "instance_id": inst.get("id"),
        "q": q_norm if q is not None else None,
        "sort": sort_f,
        "order": order_v,
    }
    fhash = _stable_hash(filters_obj)

    offset = 0
    if cursor is not None:
        ce, cobj = _read_cursor(cursor)
        if ce:
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid cursor."), 400)
        if cobj.get("v") != 1 or cobj.get("t") != "tag":
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid cursor."), 400)
        if cobj.get("fh") != fhash:
            return _log_and_return(_err("VALIDATION_ERROR", "Cursor does not match the current query."), 400)
        off = cobj.get("o")
        if not isinstance(off, int) or off < 0:
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid cursor."), 400)
        offset = off

    # ---- fetch tags ----
    ops = _load("ops_and_metadata.json")
    if not isinstance(ops, list):
        ops = []

    inst_id = inst.get("id")
    tags = []
    for r in ops:
        if r.get("instance_id") != inst_id:
            continue
        if r.get("record_type") != "tag":
            continue
        if r.get("status") == "deleted" or r.get("deleted_at") is not None:
            continue
        name = r.get("name")
        if not isinstance(name, str) or not name:
            continue
        if q is not None and q_norm:
            if q_norm not in name.lower():
                continue
        tags.append(r)

    # ---- sort ----
    reverse = (order_v == "desc")

    def _sort_key(r):
        if sort_f == "name":
            return (r.get("name") or "").lower()
        dt = _parse_dt(r.get(sort_f))
        # None last
        return (dt is None, dt)

    try:
        tags.sort(key=_sort_key, reverse=reverse)
    except Exception:
        return _log_and_return(_err("VALIDATION_ERROR", "Unable to sort by requested field."), 400)

    total = len(tags)
    page = tags[offset: offset + limit_i]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _make_cursor({"v": 1, "t": "tag", "fh": fhash, "o": next_offset}) if has_more else None

    resp = {
        "object": "list",
        "data": page,
        "instance_id": inst_id,
        "total": total,
        "limit": limit_i,
        "cursor": next_cursor,
        "has_more": has_more,
        "sort": sort_f,
        "order": order_v,
        "query": q if q is not None else None,
    }
    return _log_and_return(resp, 200)

def get_tag(instance_id, tag_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0295000" if __import__("os").path.isdir("./environment_mix/0295000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _is_str(x):
        return isinstance(x, str) and x.strip() != ""

    def _find_by_id(rows, _id):
        for r in rows:
            if isinstance(r, dict) and r.get("id") == _id:
                return r
        return None

    # --- Usage / rate limit logging (best-effort, enforced when policy exists) ---
    def _enforce_and_log(endpoint, inst_id, status_code, started_ts, extra=None):
        extra = extra or {}
        logs = _load("request_logs.json")
        policies = _load("rate_limits.json")

        now = _now()
        latency_ms = int((time.time() - started_ts) * 1000)

        # Enforce rate limits if any policy matches this endpoint/instance
        # Policy row format (flexible):
        # {id, instance_id, endpoint, window_seconds, max_requests, active}
        matched = []
        for p in policies:
            if not isinstance(p, dict):
                continue
            if p.get("active") is False:
                continue
            if p.get("instance_id") not in (None, inst_id):
                continue
            if p.get("endpoint") not in (None, endpoint):
                continue
            matched.append(p)

        # compute recent counts
        for p in matched:
            try:
                window = int(p.get("window_seconds"))
                limit = int(p.get("max_requests"))
            except Exception:
                continue
            if window <= 0 or limit < 0:
                continue
            cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=window)

            cnt = 0
            for ev in logs:
                if not isinstance(ev, dict):
                    continue
                if ev.get("endpoint") != endpoint:
                    continue
                if ev.get("instance_id") != inst_id:
                    continue
                ts = ev.get("ts")
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")) if isinstance(ts, str) else None
                except Exception:
                    dt = None
                if dt is None:
                    continue
                if dt >= cutoff:
                    cnt += 1
            if cnt >= limit:
                # log the refused call too
                logs.append(
                    {
                        "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                        "ts": now,
                        "endpoint": endpoint,
                        "instance_id": inst_id,
                        "status": "RATE_LIMIT",
                        "http_status": 429,
                        "latency_ms": latency_ms,
                        **extra,
                    }
                )
                _save("request_logs.json", logs)
                return _err("RATE_LIMIT", "Rate limit exceeded for this endpoint/instance.", policy=p)

        # log normal
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                "ts": now,
                "endpoint": endpoint,
                "instance_id": inst_id,
                "status": status_code,
                "http_status": 200 if status_code == "OK" else 400,
                "latency_ms": latency_ms,
                **extra,
            }
        )
        _save("request_logs.json", logs)
        return None

    started = time.time()

    # Validate inputs
    if not _is_str(instance_id):
        err = _err("VALIDATION_ERROR", "instance_id must be a non-empty string.")
        _enforce_and_log("get-tag", instance_id if isinstance(instance_id, str) else None, "VALIDATION_ERROR", started)
        return err
    if not _is_str(tag_id):
        err = _err("VALIDATION_ERROR", "tag_id must be a non-empty string.")
        _enforce_and_log("get-tag", instance_id, "VALIDATION_ERROR", started)
        return err

    instances = _load("instances.json")
    inst = _find_by_id(instances, instance_id)
    if not inst:
        err = _err("NOT_FOUND", "Instance not found.", instance_id=instance_id)
        _enforce_and_log("get-tag", instance_id, "NOT_FOUND", started)
        return err

    if inst.get("status") != "ready":
        err = _err("INVALID_TRANSITION", "Instance is not ready for operations.", instance_status=inst.get("status"))
        _enforce_and_log("get-tag", instance_id, "INVALID_TRANSITION", started)
        return err

    ops = _load("ops_and_metadata.json")
    tag = _find_by_id(ops, tag_id)

    if not tag or tag.get("instance_id") != instance_id or tag.get("record_type") != "tag":
        err = _err("NOT_FOUND", "Tag not found in this instance.", instance_id=instance_id, tag_id=tag_id)
        _enforce_and_log("get-tag", instance_id, "NOT_FOUND", started)
        return err

    # Exclude deleted tags
    if tag.get("status") == "deleted" or tag.get("deleted_at") is not None:
        err = _err("NOT_FOUND", "Tag not found in this instance.", instance_id=instance_id, tag_id=tag_id)
        _enforce_and_log("get-tag", instance_id, "NOT_FOUND", started)
        return err

    rl_err = _enforce_and_log("get-tag", instance_id, "OK", started, extra={"record_type": "tag", "record_id": tag_id})
    if rl_err:
        return rl_err

    return {"tag": tag}

def update_tag(instance_id, tag_id, name, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0295000" if __import__("os").path.isdir("./environment_mix/0295000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update-tag"
    status = "succeeded"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_str(x): return isinstance(x, str)

    def _is_ulid_like(s):
        if not _is_str(s) or len(s) < 8:
            return False
        return bool(re.match(r"^[a-zA-Z0-9_]+$", s))

    def _record_call(request_instance_id=None, credential=None, status="succeeded", error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "ts": _now(),
            "endpoint": endpoint,
            "instance_id": request_instance_id,
            "credential": credential,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_rate_limits(request_instance_id):
        # Simple global per-instance rolling limit: 120 requests/min.
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reversed(logs):
            if not isinstance(r, dict):
                continue
            if r.get("instance_id") != request_instance_id:
                continue
            ts = r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt < cutoff:
                break
            cnt += 1
            if cnt > 120:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    # Validate
    if not _is_str(instance_id) or not _is_ulid_like(instance_id):
        status = "failed"
        _record_call(instance_id, None, status, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_id is missing or malformed")
    if not _is_str(tag_id) or not _is_ulid_like(tag_id):
        status = "failed"
        _record_call(instance_id, None, status, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tag_id is missing or malformed")
    if not _is_str(name) or name.strip() == "":
        status = "failed"
        _record_call(instance_id, None, status, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name is missing or blank")

    rl = _enforce_rate_limits(instance_id)
    if rl:
        status = "failed"
        _record_call(instance_id, None, status, rl["error"]["code"])
        return rl

    instances = _load("instances.json")
    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if not inst:
        status = "failed"
        _record_call(instance_id, None, status, "NOT_FOUND")
        return _err("NOT_FOUND", "Instance not found")
    if inst.get("status") != "ready":
        status = "failed"
        _record_call(instance_id, None, status, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Instance is not ready for operations")
    # Ambient auth: allow if any user exists for instance; otherwise unauthorized.
    users = _load("users.json")
    if not any(isinstance(u, dict) and u.get("instance_id") == instance_id and u.get("status") in ("active", "invited", "disabled") for u in users):
        status = "failed"
        _record_call(instance_id, None, status, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized context for this instance")

    ops = _load("ops_and_metadata.json")
    tag = next((r for r in ops if isinstance(r, dict) and r.get("id") == tag_id and r.get("instance_id") == instance_id and r.get("record_type") == "tag"), None)
    if not tag:
        status = "failed"
        _record_call(instance_id, None, status, "NOT_FOUND")
        return _err("NOT_FOUND", "Tag not found in this instance")

    if tag.get("status") == "deleted":
        # allow rename of deleted? Realistic behavior: treat as not found for update.
        status = "failed"
        _record_call(instance_id, None, status, "NOT_FOUND")
        return _err("NOT_FOUND", "Tag not found in this instance")

    new_name = name.strip()
    new_norm = new_name.casefold()
    # Unique (case-insensitive) per instance where status!='deleted'
    for r in ops:
        if not isinstance(r, dict):
            continue
        if r.get("instance_id") != instance_id or r.get("record_type") != "tag":
            continue
        if r.get("id") == tag_id:
            continue
        if r.get("status") == "deleted":
            continue
        rn = r.get("name")
        if isinstance(rn, str) and rn.strip().casefold() == new_norm:
            status = "failed"
            _record_call(instance_id, None, status, "CONFLICT")
            return _err("CONFLICT", "Tag name already exists in this instance")

    # Mutate
    tag["name"] = new_name
    tag["updated_at"] = _now()
    # If a tag was inactive, keep status; if missing status, set active.
    if tag.get("status") not in ("active", "inactive", "deleted"):
        tag["status"] = "active"

    _save("ops_and_metadata.json", ops)

    _record_call(instance_id, None, status, None)
    return {"tag": tag}

def delete_tag(instance_id, tag_id, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0295000" if __import__("os").path.isdir("./environment_mix/0295000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _endpoint = "delete-tag"
    _now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _new_req_id():
        return f"req_{int(time.time()*1000)}_{random.randrange(100000,999999)}"

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        s = ts.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status, error_code=None, **extra):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_req_id(),
            "endpoint": _endpoint,
            "instance_id": instance_id if isinstance(instance_id, str) else None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now,
            **(extra or {})
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        cfg = _load("service_config.json")
        limit_per_min = None
        quota_per_day = None
        if isinstance(cfg, dict):
            limit_per_min = cfg.get("rate_limit_per_minute") or cfg.get("requests_per_minute")
            quota_per_day = cfg.get("quota_per_day") or cfg.get("requests_per_day")
        elif isinstance(cfg, list) and cfg and isinstance(cfg[0], dict):
            limit_per_min = cfg[0].get("rate_limit_per_minute") or cfg[0].get("requests_per_minute")
            quota_per_day = cfg[0].get("quota_per_day") or cfg[0].get("requests_per_day")
        if limit_per_min is None and quota_per_day is None:
            return None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = _parse_ts(_now)
        if now_dt is None:
            return None

        inst_logs = []
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("instance_id") != instance_id:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is not None:
                inst_logs.append(ts)

        if limit_per_min is not None:
            try:
                rpm = int(limit_per_min)
                if rpm >= 0:
                    cutoff = now_dt - datetime.timedelta(seconds=60)
                    if sum(1 for ts in inst_logs if ts >= cutoff) >= rpm:
                        return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=rpm, instance_id=instance_id)
            except Exception:
                pass

        if quota_per_day is not None:
            try:
                qd = int(quota_per_day)
                if qd >= 0:
                    cutoff = now_dt - datetime.timedelta(days=1)
                    if sum(1 for ts in inst_logs if ts >= cutoff) >= qd:
                        return _err("QUOTA_EXCEEDED", "Daily quota exceeded", quota_per_day=qd, instance_id=instance_id)
            except Exception:
                pass
        return None

    if not isinstance(instance_id, str) or not instance_id.startswith("n8n_inst_"):
        out = _err("VALIDATION_ERROR", "Invalid instance_id")
        _log("error", out["error"]["code"])
        return out
    if not isinstance(tag_id, str) or not tag_id:
        out = _err("VALIDATION_ERROR", "Invalid tag_id")
        _log("error", out["error"]["code"])
        return out

    limited = _enforce_limits()
    if limited:
        _log("error", limited["error"]["code"])
        return limited

    instances = _load("instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if not inst:
        out = _err("NOT_FOUND", "Instance not found", instance_id=instance_id)
        _log("error", out["error"]["code"])
        return out
    if inst.get("status") != "ready":
        out = _err("INVALID_TRANSITION", "Instance is not ready for tag operations", instance_status=inst.get("status"), required_status="ready", instance_id=instance_id)
        _log("error", out["error"]["code"])
        return out

    ops = _load("ops_and_metadata.json")
    if not isinstance(ops, list):
        ops = []
    idx = None
    tag = None
    for i, r in enumerate(ops):
        if isinstance(r, dict) and r.get("id") == tag_id and r.get("instance_id") == instance_id and r.get("record_type") == "tag":
            idx = i
            tag = r
            break
    if tag is None:
        out = _err("NOT_FOUND", "Tag not found in this instance", instance_id=instance_id, tag_id=tag_id)
        _log("error", out["error"]["code"])
        return out

    # Idempotent delete
    if tag.get("status") == "deleted":
        _log("ok")
        return {"tag": tag, "changed": False}

    if tag.get("status") not in ("active", "inactive"):
        out = _err("INVALID_TRANSITION", "Cannot delete tag from current status", from_status=tag.get("status"), to_status="deleted", tag_id=tag_id)
        _log("error", out["error"]["code"])
        return out

    tag2 = dict(tag)
    tag2["status"] = "deleted"
    tag2["deleted_at"] = _now
    tag2["updated_at"] = _now
    ops[idx] = tag2

    # Also soft-delete workflow_tag mappings referencing this tag (best-effort, consistent with joins excluding deleted)
    changed_mappings = 0
    for j, r in enumerate(ops):
        if not isinstance(r, dict):
            continue
        if r.get("instance_id") != instance_id:
            continue
        if r.get("record_type") == "workflow_tag" and r.get("tag_id") == tag_id and r.get("status") != "deleted":
            r2 = dict(r)
            r2["status"] = "deleted"
            r2["deleted_at"] = _now
            r2["updated_at"] = _now
            ops[j] = r2
            changed_mappings += 1

    _save("ops_and_metadata.json", ops)
    _log("ok", deleted_mappings=changed_mappings)
    return {"tag": tag2, "changed": True, "deleted_workflow_tag_mappings": changed_mappings}

