        return _err("NOT_FOUND", "Workflow not found in this instance")

    ops = _load("ops_and_metadata.json")

    # Ensure tags exist in instance and are not deleted; keep order but ensure uniqueness in resulting mapping
    tag_by_id = {r.get("id"): r for r in ops if isinstance(r, dict) and r.get("instance_id") == instance_id and r.get("record_type") == "tag"}
    seen = set()
    ordered_unique_tag_ids = []
    for tid in tag_ids:
        if tid in seen:
            continue
        seen.add(tid)
        ordered_unique_tag_ids.append(tid)

    for tid in ordered_unique_tag_ids:
        tr = tag_by_id.get(tid)
        if not tr or tr.get("status") == "deleted":
            status = "failed"
            _record_call(instance_id, None, status, "NOT_FOUND")
            return _err("NOT_FOUND", f"Tag not found in this instance: {tid}")

    # Replace: soft-delete existing mappings, then create/ensure new set active
    now = _now()
    existing = []
    for r in ops:
        if not isinstance(r, dict):
            continue
        if r.get("instance_id") != instance_id:
            continue
        if r.get("record_type") != "workflow_tag":
            continue
        if r.get("workflow_id") != workflow_id:
            continue
        if r.get("status") == "deleted":
            continue
        existing.append(r)

    # Soft-delete all existing active mappings for this workflow
    for m in existing:
        m["status"] = "deleted"
        m["deleted_at"] = now
        m["updated_at"] = now

    # Helper: find mapping by (workflow_id, tag_id) even if deleted (for idempotency)
