            if r.get("workflow_id") == wid and r.get("tag_id") == tid:
                return r
        return None

    # Create or reactivate mappings in the provided order
    created_any = False
    for tid in ordered_unique_tag_ids:
        m = _find_mapping(workflow_id, tid)
        if m and m.get("status") != "deleted":
            # Shouldn't happen because we deleted all above, but keep safe
            m["updated_at"] = now
        elif m and m.get("status") == "deleted":
            # Reactivate
            m["status"] = "active"
            m["deleted_at"] = None
            m["updated_at"] = now
            if not isinstance(m.get("created_at"), str):
                m["created_at"] = now
        else:
            # New mapping record
            new_id = "n8n_meta_" + uuid.uuid4().hex
            ops.append({
                "id": new_id,
                "instance_id": instance_id,
                "record_type": "workflow_tag",
                "status": "active",
                "ref_id": None,
                "workflow_id": workflow_id,
                "tag_id": tid,
                "project_id": wf.get("project_id"),
                "user_id": None,
                "name": None,
                "type_name": None,
                "data": None,
                "started_at": None,
                "finished_at": None,
                "created_at": now,
                "updated_at": now,
                "deleted_at": None,
            })
            created_any = True

    # Ensure uniqueness invariant for active mappings per (workflow_id, tag_id)
    active_pairs = set()
    for r in ops:
        if not isinstance(r, dict):
            continue
        if r.get("instance_id") != instance_id or r.get("record_type") != "workflow_tag":
            continue
        if r.get("status") == "deleted":
            continue
        if r.get("workflow_id") != workflow_id:
            continue
        pair = (r.get("workflow_id"), r.get("tag_id"))
        if pair in active_pairs:
            # Resolve by deleting duplicates deterministically (keep earliest created_at)
            pass
        else:
            active_pairs.add(pair)

    # Deduplicate if needed
    # Keep one active mapping per tag_id: earliest created_at (then id), delete the rest
    per_tid = {}
    for r in ops:
        if not isinstance(r, dict):
            continue
        if r.get("instance_id") != instance_id or r.get("record_type") != "workflow_tag":
            continue
        if r.get("workflow_id") != workflow_id:
            continue
        if r.get("status") == "deleted":
            continue
        tid = r.get("tag_id")
        if not isinstance(tid, str):
            continue
        ca = r.get("created_at") if isinstance(r.get("created_at"), str) else ""
        key = (ca, r.get("id") or "")
        if tid not in per_tid or key < per_tid[tid][0]:
            per_tid[tid] = (key, r)
    # delete other active mappings with same tid
    keep_ids = {v[1].get("id") for v in per_tid.values() if isinstance(v[1], dict)}
    for r in ops:
        if not isinstance(r, dict):
            continue
        if r.get("instance_id") != instance_id or r.get("record_type") != "workflow_tag":
            continue
        if r.get("workflow_id") != workflow_id:
            continue
        if r.get("status") == "deleted":
            continue
        tid = r.get("tag_id")
        if isinstance(tid, str) and r.get("id") not in keep_ids:
            r["status"] = "deleted"
            r["deleted_at"] = now
            r["updated_at"] = now

    # Persist
    _save("ops_and_metadata.json", ops)

    # Return associated tags in requested order, excluding deleted
    tags = []
    for tid in ordered_unique_tag_ids:
        tr = tag_by_id.get(tid)
        if tr and tr.get("status") != "deleted":
            tags.append(tr)

    _record_call(instance_id, None, status, None)
    return {"workflow_id": workflow_id, "instance_id": instance_id, "tags": tags, "count": len(tags)}

def generate_audit(instance_id, project_id=None, from_at=None, to_at=None, include=None, format=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0295000" if __import__("os").path.isdir("./environment_mix/0295000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now():
        return _now_dt().isoformat()

    def _is_str(x):
        return isinstance(x, str) and x.strip() != ""

    def _find_by_id(rows, _id):
        for r in rows:
            if isinstance(r, dict) and r.get("id") == _id:
                return r
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            raise ValueError("datetime must be a non-empty RFC3339 string")
        ss = s.strip()
        # Accept Z
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        return datetime.datetime.fromisoformat(ss)

    def _redact(obj):
        # Conservative redaction: remove common secret-bearing keys anywhere in the structure.
        secret_keys = {
            "password",
            "pass",
            "secret",
            "token",
            "api_key",
            "apikey",
            "access_token",
            "refresh_token",
            "client_secret",
            "authorization",
            "auth",
            "cookie",
            "set-cookie",
            "private_key",
        }
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                if isinstance(k, str) and k.lower() in secret_keys:
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _redact(v)
            return out
        if isinstance(obj, list):
            return [_redact(v) for v in obj]
        return obj

    def _gen_id(prefix):
        # Deterministic-enough offline ULID-ish (not a true ULID): prefix + base32 of time+pid+counter hash
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(8).hex()}".encode("utf-8")
        h = hashlib.sha256(raw).digest()
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        # take 16 bytes => 26 base32 chars approx, but we produce 16 chars for compactness
        n = int.from_bytes(h[:10], "big")
        chars = []
        for _ in range(16):
            n, r = divmod(n, 32)
            chars.append(alphabet[r])
        return f"{prefix}_{''.join(reversed(chars))}"

    # --- Usage / rate limit logging (best-effort, enforced when policy exists) ---
    def _enforce_and_log(endpoint, inst_id, status_code, started_ts, extra=None):
        extra = extra or {}
        logs = _load("request_logs.json")
        policies = _load("rate_limits.json")

        now = _now()
        latency_ms = int((time.time() - started_ts) * 1000)

        matched = []
        for p in policies:
            if not isinstance(p, dict):
                continue
            if p.get("active") is False:
                continue
            if p.get("instance_id") not in (None, inst_id):
                continue
            if p.get("endpoint") not in (None, endpoint):
                continue
            matched.append(p)

        for p in matched:
            try:
                window = int(p.get("window_seconds"))
                limit = int(p.get("max_requests"))
            except Exception:
                continue
            if window <= 0 or limit < 0:
                continue
            cutoff = _now_dt() - datetime.timedelta(seconds=window)
            cnt = 0
            for ev in logs:
                if not isinstance(ev, dict):
                    continue
                if ev.get("endpoint") != endpoint:
                    continue
                if ev.get("instance_id") != inst_id:
                    continue
                ts = ev.get("ts")
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")) if isinstance(ts, str) else None
                except Exception:
                    dt = None
                if dt is None:
                    continue
                if dt >= cutoff:
                    cnt += 1
            if cnt >= limit:
                logs.append(
                    {
                        "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                        "ts": now,
                        "endpoint": endpoint,
                        "instance_id": inst_id,
                        "status": "RATE_LIMIT",
                        "http_status": 429,
                        "latency_ms": latency_ms,
                        **extra,
                    }
                )
                _save("request_logs.json", logs)
                return _err("RATE_LIMIT", "Rate limit exceeded for this endpoint/instance.", policy=p)

        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                "ts": now,
                "endpoint": endpoint,
                "instance_id": inst_id,
                "status": status_code,
                "http_status": 200 if status_code == "OK" else 400,
                "latency_ms": latency_ms,
                **extra,
            }
        )
        _save("request_logs.json", logs)
        return None

    started = time.time()

    # Validate inputs
    if not _is_str(instance_id):
        err = _err("VALIDATION_ERROR", "instance_id must be a non-empty string.")
        _enforce_and_log("generate-audit", instance_id if isinstance(instance_id, str) else None, "VALIDATION_ERROR", started)
        return err

    if project_id is not None:
        if not _is_str(project_id):
            err = _err("VALIDATION_ERROR", "project_id must be a string when provided.")
            _enforce_and_log("generate-audit", instance_id, "VALIDATION_ERROR", started)
            return err
        if not re.match(r"^n8n_prj_[0-9A-HJKMNP-TV-Z]{10,}$", project_id):
            err = _err("VALIDATION_ERROR", "project_id is malformed.", project_id=project_id)
            _enforce_and_log("generate-audit", instance_id, "VALIDATION_ERROR", started)
            return err

    if not re.match(r"^n8n_inst_[0-9A-HJKMNP-TV-Z]{10,}$", instance_id):
        err = _err("VALIDATION_ERROR", "instance_id is malformed.", instance_id=instance_id)
        _enforce_and_log("generate-audit", instance_id, "VALIDATION_ERROR", started)
        return err

    try:
        from_dt = _parse_dt(from_at) if from_at is not None else None
        to_dt = _parse_dt(to_at) if to_at is not None else None
    except ValueError as e:
        err = _err("VALIDATION_ERROR", f"Invalid datetime: {str(e)}")
        _enforce_and_log("generate-audit", instance_id, "VALIDATION_ERROR", started)
        return err

    if from_dt and to_dt and from_dt > to_dt:
        err = _err("VALIDATION_ERROR", "from_at must be before or equal to to_at.")
        _enforce_and_log("generate-audit", instance_id, "VALIDATION_ERROR", started)
        return err

    allowed_sections = {"workflows", "executions", "users", "projects", "variables", "credentials", "tags"}
    if include is not None:
        if not isinstance(include, list) or any(not isinstance(x, str) for x in include):
            err = _err("VALIDATION_ERROR", "include must be an array of strings when provided.")
            _enforce_and_log("generate-audit", instance_id, "VALIDATION_ERROR", started)
            return err
        bad = [x for x in include if x not in allowed_sections]
        if bad:
            err = _err("VALIDATION_ERROR", "include contains unsupported sections.", unsupported=bad)
            _enforce_and_log("generate-audit", instance_id, "VALIDATION_ERROR", started)
            return err
        sections = include[:]  # preserve order
    else:
        sections = ["workflows", "executions", "users", "projects", "variables", "credentials", "tags"]

    if format is None:
        fmt = "json"
    else:
        if not isinstance(format, str):
            err = _err("VALIDATION_ERROR", "format must be a string when provided.")
            _enforce_and_log("generate-audit", instance_id, "VALIDATION_ERROR", started)
            return err
        if format not in ("json", "pdf"):
            err = _err("VALIDATION_ERROR", "format must be one of: json, pdf.")
            _enforce_and_log("generate-audit", instance_id, "VALIDATION_ERROR", started)
            return err
        fmt = format

    instances = _load("instances.json")
    inst = _find_by_id(instances, instance_id)
    if not inst:
        err = _err("NOT_FOUND", "Instance not found.", instance_id=instance_id)
        _enforce_and_log("generate-audit", instance_id, "NOT_FOUND", started)
        return err

    if inst.get("status") != "ready":
        err = _err("INVALID_TRANSITION", "Instance is not ready for operations.", instance_status=inst.get("status"))
        _enforce_and_log("generate-audit", instance_id, "INVALID_TRANSITION", started)
        return err

    if not inst.get("cap_audit_enabled", False):
        err = _err("CONFLICT", "Audit capability is not enabled for this instance.", capability="cap_audit_enabled")
        _enforce_and_log("generate-audit", instance_id, "CONFLICT", started)
        return err

    projects = _load("projects.json")
    prj = None
    if project_id is not None:
        prj = _find_by_id(projects, project_id)
        if not prj or prj.get("instance_id") != instance_id or prj.get("status") == "deleted" or prj.get("deleted_at") is not None:
            err = _err("NOT_FOUND", "Project not found in this instance.", project_id=project_id)
            _enforce_and_log("generate-audit", instance_id, "NOT_FOUND", started)
            return err

    # Rate-limit check before doing heavy work
    rl_err = _enforce_and_log("generate-audit", instance_id, "OK", started, extra={"phase": "rate_limit_check"})
    if rl_err:
        return rl_err

    ops = _load("ops_and_metadata.json")

    # Create audit_report record queued -> running -> succeeded/failed
    now = _now()
    audit_id = _gen_id("n8n_aud")
    audit_row = {
        "id": audit_id,
        "instance_id": instance_id,
        "record_type": "audit_report",
        "status": "queued",
        "ref_id": None,
        "workflow_id": None,
        "tag_id": None,
        "project_id": project_id,
        "user_id": None,
        "name": f"audit_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%SZ')}",
        "type_name": None,
        "data": {
            "requested": {
                "from_at": from_at,
                "to_at": to_at,
                "include": sections,
                "format": fmt,
                "project_id": project_id,
            }
        },
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
        "deleted_at": None,
    }
    ops.append(audit_row)
    _save("ops_and_metadata.json", ops)

    # Transition to running
    audit_row["status"] = "running"
    audit_row["started_at"] = _now()
    audit_row["updated_at"] = _now()
    _save("ops_and_metadata.json", ops)

    # Build report payload
    try:
        workflows = _load("workflows.json")
        users = _load("users.json")

        # Helper filters
        def _in_range(dt_iso):
            if dt_iso is None:
                return False
            try:
                dt = datetime.datetime.fromisoformat(dt_iso.replace("Z", "+00:00")) if isinstance(dt_iso, str) else None
            except Exception:
                return False
            if dt is None:
                return False
            if from_dt and dt < from_dt:
                return False
            if to_dt and dt > to_dt:
                return False
            return True

        # Scope: instance, optional project
        wf_rows = [
            w for w in workflows
            if isinstance(w, dict)
            and w.get("instance_id") == instance_id
            and w.get("status") != "deleted"
            and w.get("deleted_at") is None
            and (project_id is None or w.get("project_id") == project_id)
        ]

        usr_rows = [
            u for u in users
            if isinstance(u, dict)
            and u.get("instance_id") == instance_id
            and u.get("status") != "deleted"
            and u.get("deleted_at") is None
        ]

        prj_rows = [
            p for p in projects
            if isinstance(p, dict)
            and p.get("instance_id") == instance_id
            and p.get("status") != "deleted"
            and p.get("deleted_at") is None
            and (project_id is None or p.get("id") == project_id)
        ]

        # ops subtypes
        def _ops_rows(rt):
            rows = []
            for r in ops:
                if not isinstance(r, dict):
                    continue
                if r.get("instance_id") != instance_id:
                    continue
                if r.get("record_type") != rt:
                    continue
                if r.get("status") == "deleted" or r.get("deleted_at") is not None:
                    continue
                if project_id is not None and r.get("project_id") not in (None, project_id):
                    # Many n8n entities may not be project-scoped; keep only matching or unscoped? We'll keep matching only.
                    # But for tags, variables, credentials, project_id can scope them; for executions it's workflow-scoped.
                    if rt in ("tag", "variable", "credential", "workflow_tag"):
                        continue
                rows.append(r)
            return rows

        # executions filtered by workflow scope + time range (started_at)
        exec_rows_all = _ops_rows("execution")
        wf_ids = {w.get("id") for w in wf_rows}
        exec_rows = []
        for e in exec_rows_all:
            if e.get("workflow_id") not in wf_ids:
                continue
            if from_dt or to_dt:
                # Use started_at if present, else created_at
                ts = e.get("started_at") or e.get("created_at")
                if not _in_range(ts):
                    continue
            exec_rows.append(e)

        tag_rows = _ops_rows("tag")
        var_rows = _ops_rows("variable")
        cred_rows = _ops_rows("credential")

        # Summaries
        payload = {
            "meta": {
                "instance_id": instance_id,
                "project_id": project_id,
                "project_name": prj.get("name") if prj else None,
                "generated_at": _now(),
                "from_at": from_at,
                "to_at": to_at,
                "include": sections,
                "format": fmt,
            },
            "summary": {
                "workflows": len(wf_rows) if "workflows" in sections else None,
                "executions": len(exec_rows) if "executions" in sections else None,
                "users": len(usr_rows) if "users" in sections else None,
                "projects": len(prj_rows) if "projects" in sections else None,
                "variables": len(var_rows) if "variables" in sections else None,
                "credentials": len(cred_rows) if "credentials" in sections else None,
                "tags": len(tag_rows) if "tags" in sections else None,
            },
        }

        if "workflows" in sections:
            payload["workflows"] = [_redact(w) for w in wf_rows]
        if "executions" in sections:
            payload["executions"] = [_redact(e) for e in exec_rows]
        if "users" in sections:
            payload["users"] = [_redact(u) for u in usr_rows]
        if "projects" in sections:
            payload["projects"] = [_redact(p) for p in prj_rows]
        if "variables" in sections:
            payload["variables"] = [_redact(v) for v in var_rows]
        if "credentials" in sections:
            payload["credentials"] = [_redact(c) for c in cred_rows]
        if "tags" in sections:
            payload["tags"] = [_redact(t) for t in tag_rows]

        # Finish audit row
        audit_row["status"] = "succeeded"
        audit_row["finished_at"] = _now()
        audit_row["updated_at"] = _now()
        audit_row["data"] = _redact({"report": payload, **(audit_row.get("data") or {})})
        _save("ops_and_metadata.json", ops)

        # Return in requested format
        if fmt == "json":
            body = {"audit_report": audit_row, "format": "json", "report": payload}
        else:
            # Offline "pdf": return a minimal PDF-like byte string as base64 for transport safety
            import base64
            text = json.dumps(payload, ensure_ascii=False, indent=2)
            pseudo_pdf = ("%PDF-1.4\n% n8n integration server pseudo-pdf\n" + text + "\n%%EOF\n").encode("utf-8")
            body = {
                "audit_report": audit_row,
                "format": "pdf",
                "content_base64": base64.b64encode(pseudo_pdf).decode("ascii"),
                "content_type": "application/pdf",
                "filename": f"{audit_row.get('name','audit')}.pdf",
            }

        # Log call (already rate-limit logged once; record completion too)
        _enforce_and_log("generate-audit", instance_id, "OK", started, extra={"record_type": "audit_report", "record_id": audit_id})
        return body

    except Exception as e:
        # Mark audit as failed and persist
        try:
            audit_row["status"] = "failed"
            audit_row["finished_at"] = _now()
            audit_row["updated_at"] = _now()
            audit_row["data"] = _redact(
                {
                    **(audit_row.get("data") or {}),
                    "error": {"message": str(e), "type": e.__class__.__name__},
                }
            )
            _save("ops_and_metadata.json", ops)
        except Exception:
            pass
        _enforce_and_log("generate-audit", instance_id, "CONFLICT", started, extra={"record_type": "audit_report", "record_id": audit_id})
        return _err("CONFLICT", "Audit generation failed.", audit_report_id=audit_id)

def list_instances(status=None, base_url=None, owner_user_id=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0295000" if __import__("os").path.isdir("./environment_mix/0295000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _log(status_s, meta=None):
        for fname in ("request_logs.json", "usage.json", "audit_log.json", "api_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                if not isinstance(logs, list):
                    logs = []
                rec = {
                    "id": "req_" + hashlib.sha256(f"{time.time_ns()}:{os.getpid()}".encode()).hexdigest()[:24],
                    "endpoint": "list-instances",
                    "instance_id": None,
                    "status": status_s,
                    "timestamp": now,
                    "latency_ms": int((time.time() - t0) * 1000),
                }
                if meta:
                    rec["meta"] = meta
                logs.append(rec)
                _save(fname, logs)
                break

    # Ambient auth: if there is any instance data, allow; if store empty, treat as unauthorized.
    instances = _load("instances.json")
    if not isinstance(instances, list):
        instances = []
    if len(instances) == 0:
        _log("error", {"reason": "no_visible_instances"})
        return _err("UNAUTHORIZED", "Not authenticated or not entitled to view instances")

    # validate filters
    if status is not None:
        if not isinstance(status, str) or status not in ("provisioning", "ready", "error", "disabled"):
            _log("error", {"reason": "invalid_status"})
            return _err("VALIDATION_ERROR", "status must be one of provisioning, ready, error, disabled", field="status")

    if base_url is not None:
        if not isinstance(base_url, str) or not base_url.strip():
            _log("error", {"reason": "invalid_base_url"})
            return _err("VALIDATION_ERROR", "base_url must be a non-empty string", field="base_url")

    if owner_user_id is not None:
        if not isinstance(owner_user_id, str) or not re.match(r"^n8n_usr_[0-9A-HJKMNP-TV-Z]{10,}$", owner_user_id):
            _log("error", {"reason": "invalid_owner_user_id"})
            return _err("VALIDATION_ERROR", "owner_user_id is malformed", field="owner_user_id")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", {"reason": "invalid_limit"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        _log("error", {"reason": "invalid_cursor"})
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "display_name"):
        _log("error", {"reason": "invalid_sort"})
        return _err("VALIDATION_ERROR", "sort must be one of created_at, updated_at, display_name", field="sort")

    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        _log("error", {"reason": "invalid_order"})
        return _err("VALIDATION_ERROR", "order must be one of asc, desc", field="order")

    # filter
    rows = []
    bu = base_url.lower().strip() if isinstance(base_url, str) else None
    for r in instances:
        if not isinstance(r, dict):
            continue
        # instances don't have deleted status; include all statuses but allow filtering
        if status is not None and r.get("status") != status:
            continue
        if bu is not None:
            if not isinstance(r.get("base_url"), str) or r.get("base_url").lower() != bu:
                continue
        if owner_user_id is not None and r.get("owner_user_id") != owner_user_id:
            continue
        rows.append(r)

    # sort
    def _key(x):
        v = x.get(sort)
        if v is None:
            return ""
        return v
    reverse = (order == "desc")
    try:
        rows.sort(key=_key, reverse=reverse)
    except TypeError:
        # mixed types; fallback stable string sort
        rows.sort(key=lambda x: str(_key(x)), reverse=reverse)

    # pagination cursor: interpret as integer offset if possible, else treat as 0
    offset = 0
    if cursor:
        try:
            offset = int(cursor, 10)
            if offset < 0:
                offset = 0
        except ValueError:
            offset = 0

    total = len(rows)
    page = rows[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = str(next_off) if has_more else None

    # response projection
    out = []
    for r in page:
        out.append({
            "id": r.get("id"),
            "display_name": r.get("display_name"),
            "base_url": r.get("base_url"),
            "auth_type": r.get("auth_type"),
            "cap_projects_enabled": bool(r.get("cap_projects_enabled", False)),
            "cap_variables_enabled": bool(r.get("cap_variables_enabled", False)),
            "cap_audit_enabled": bool(r.get("cap_audit_enabled", False)),
            "owner_user_id": r.get("owner_user_id"),
            "status": r.get("status"),
            "last_healthcheck_at": r.get("last_healthcheck_at"),
            "last_error": r.get("last_error"),
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at"),
        })

    _log("ok", {"returned": len(out), "total": total, "has_more": has_more})
    return {
        "instances": out,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order,
        },
    }

def get_instance(instance_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0295000" if __import__("os").path.isdir("./environment_mix/0295000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # rate/quota + request logging (best-effort; if cannot log, still proceed)
    def _enforce_and_log(status_code, endpoint, credential_id=None, instance_ctx=None, extra=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
        except Exception:
            logs = []

        # Basic sliding-window rate limit: 120 req/min per instance_id (or global if none)
        # Basic daily quota: 5000 req/day per instance_id (or global if none)
        window_s = 60
        limit_per_window = 120
        daily_limit = 5000

        key = instance_ctx or "global"
        # parse timestamps stored as ISOZ; tolerate parse failures by ignoring those rows
        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s2 = s[:-1]
                else:
                    s2 = s
                return datetime.datetime.fromisoformat(s2)
            except Exception:
                return None

        now_dt = datetime.datetime.utcnow().replace(microsecond=0)
        win_start = now_dt - datetime.timedelta(seconds=window_s)
        day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)

        recent = 0
        today = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("scope") != key:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= win_start:
                recent += 1
            if ts >= day_start:
                today += 1

        # Enforce before appending current request row (so limits are exact)
        if recent >= limit_per_window:
            # log refused call
            logs.append({
                "id": "req_" + re.sub(r"[^0-9A-Za-z]+", "", now) + "_" + str(len(logs) + 1),
                "timestamp": now,
                "endpoint": endpoint,
                "scope": key,
                "credential_id": credential_id,
                "instance_id": instance_ctx,
                "status": "RATE_LIMIT",
                "http_status": 429,
                "latency_ms": int((time.time() - t0) * 1000),
                "meta": extra or {}
            })
            try:
                _save("request_logs.json", logs)
            except Exception:
                pass
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if today >= daily_limit:
            logs.append({
                "id": "req_" + re.sub(r"[^0-9A-Za-z]+", "", now) + "_" + str(len(logs) + 1),
                "timestamp": now,
                "endpoint": endpoint,
                "scope": key,
                "credential_id": credential_id,
                "instance_id": instance_ctx,
                "status": "QUOTA_EXCEEDED",
                "http_status": 429,
                "latency_ms": int((time.time() - t0) * 1000),
                "meta": extra or {}
            })
            try:
                _save("request_logs.json", logs)
            except Exception:
                pass
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

        logs.append({
            "id": "req_" + re.sub(r"[^0-9A-Za-z]+", "", now) + "_" + str(len(logs) + 1),
            "timestamp": now,
            "endpoint": endpoint,
            "scope": key,
            "credential_id": credential_id,
            "instance_id": instance_ctx,
            "status": status_code,
            "http_status": 200 if status_code == "OK" else 400,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": extra or {}
        })
        try:
            _save("request_logs.json", logs)
        except Exception:
            pass
        return None

    # Validate
    if not isinstance(instance_id, str):
        e = _err("VALIDATION_ERROR", "instance_id must be a string")
        _enforce_and_log("VALIDATION_ERROR", "get-instance", instance_ctx=None, extra={"instance_id": instance_id})
        return e
    if not re.match(r"^n8n_inst_[0-9A-HJKMNP-TV-Z]{10,}$", instance_id):
        e = _err("VALIDATION_ERROR", "instance_id does not match required pattern")
        _enforce_and_log("VALIDATION_ERROR", "get-instance", instance_ctx=None, extra={"instance_id": instance_id})
        return e

    # Resolve "ambient auth": pick a visible instance that can serve the call.
    # Since no explicit credentials exist in the schema for callers, treat visibility as: instance exists.
    instances = _load("instances.json")
    if not isinstance(instances, list):
        instances = []

    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if not inst:
        e = _err("NOT_FOUND", "Instance not found")
        _enforce_and_log("NOT_FOUND", "get-instance", instance_ctx=instance_id)
        return e

    # Enforce ready-instance scoping: tools (except init-n8n) require status == ready.
    if inst.get("status") != "ready":
        e = _err("NOT_FOUND", "Instance not found")
        _enforce_and_log("NOT_FOUND", "get-instance", instance_ctx=instance_id, extra={"reason": "instance_not_ready"})
        return e

    _enforce_and_log("OK", "get-instance", instance_ctx=instance_id)
    return {"instance": inst}

