        day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)

        recent = 0
        today = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("scope") != key:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= win_start:
                recent += 1
            if ts >= day_start:
                today += 1

        if recent >= limit_per_window:
            logs.append({
                "id": "req_" + re.sub(r"[^0-9A-Za-z]+", "", now) + "_" + str(len(logs) + 1),
                "timestamp": now,
                "endpoint": endpoint,
                "scope": key,
                "credential_id": credential_id,
                "instance_id": instance_ctx,
                "status": "RATE_LIMIT",
                "http_status": 429,
                "latency_ms": int((time.time() - t0) * 1000),
                "meta": extra or {}
            })
