        if today >= daily_limit:
            logs.append({
                "id": "req_" + re.sub(r"[^0-9A-Za-z]+", "", now) + "_" + str(len(logs) + 1),
                "timestamp": now,
                "endpoint": endpoint,
                "scope": key,
                "credential_id": credential_id,
                "instance_id": instance_ctx,
                "status": "QUOTA_EXCEEDED",
                "http_status": 429,
                "latency_ms": int((time.time() - t0) * 1000),
                "meta": extra or {}
            })
            try:
                _save("request_logs.json", logs)
            except Exception:
                pass
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

        logs.append({
            "id": "req_" + re.sub(r"[^0-9A-Za-z]+", "", now) + "_" + str(len(logs) + 1),
