        _enforce_and_log("VALIDATION_ERROR", "update-instance", instance_ctx=instance_id)
        return e

    if base_url is not None and not isinstance(base_url, str):
        e = _err("VALIDATION_ERROR", "base_url must be a string")
        _enforce_and_log("VALIDATION_ERROR", "update-instance", instance_ctx=instance_id)
        return e

    if auth_type is not None:
        if not isinstance(auth_type, str):
            e = _err("VALIDATION_ERROR", "auth_type must be a string")
            _enforce_and_log("VALIDATION_ERROR", "update-instance", instance_ctx=instance_id)
