        if auth_type not in ["api_key", "basic", "oauth2", "none"]:
            e = _err("VALIDATION_ERROR", "auth_type must be one of: api_key, basic, oauth2, none")
            _enforce_and_log("VALIDATION_ERROR", "update-instance", instance_ctx=instance_id)
