            _enforce_and_log("VALIDATION_ERROR", "update-instance", instance_ctx=instance_id)
            return e
        if not re.match(r"^n8n_usr_[0-9A-HJKMNP-TV-Z]{10,}$", owner_user_id):
            e = _err("VALIDATION_ERROR", "owner_user_id does not match required pattern")
            _enforce_and_log("VALIDATION_ERROR", "update-instance", instance_ctx=instance_id)
            return e

    # Load store
    instances = _load("instances.json")
    if not isinstance(instances, list):
        instances = []
    users = _load("users.json")
    if not isinstance(users, list):
        users = []

    inst_idx = None
    inst = None
    for i, r in enumerate(instances):
        if isinstance(r, dict) and r.get("id") == instance_id:
            inst_idx = i
            inst = r
            break
    if inst is None:
        e = _err("NOT_FOUND", "Instance not found")
        _enforce_and_log("NOT_FOUND", "update-instance", instance_ctx=instance_id)
        return e

    # Enforce ready-instance scoping (except init-n8n)
    if inst.get("status") != "ready":
        e = _err("NOT_FOUND", "Instance not found")
        _enforce_and_log("NOT_FOUND", "update-instance", instance_ctx=instance_id, extra={"reason": "instance_not_ready"})
        return e

    # Validate URL if provided
    def _valid_url(u):
        try:
            p = urllib.parse.urlparse(u)
            if p.scheme not in ("http", "https"):
                return False
            if not p.netloc:
                return False
            # disallow whitespace
            if any(c.isspace() for c in u):
                return False
            return True
        except Exception:
            return False

    if base_url is not None and not _valid_url(base_url):
        e = _err("VALIDATION_ERROR", "base_url must be a valid URL")
        _enforce_and_log("VALIDATION_ERROR", "update-instance", instance_ctx=instance_id, extra={"base_url": base_url})
        return e

    # Uniqueness: unique(base_url)
    if base_url is not None:
        for r in instances:
            if not isinstance(r, dict):
                continue
            if r.get("id") != instance_id and r.get("base_url") == base_url:
                e = _err("CONFLICT", "base_url collides with an existing instance connection")
                _enforce_and_log("CONFLICT", "update-instance", instance_ctx=instance_id, extra={"base_url": base_url})
                return e

    # auth_secret_ref compatibility / requirement
    new_auth_type = auth_type if auth_type is not None else inst.get("auth_type")
    new_auth_secret_ref = auth_secret_ref if auth_secret_ref is not None else inst.get("auth_secret_ref")

    if new_auth_type != "none" and (new_auth_secret_ref is None or (isinstance(new_auth_secret_ref, str) and new_auth_secret_ref.strip() == "")):
        e = _err("VALIDATION_ERROR", "auth_type != 'none' requires auth_secret_ref")
        _enforce_and_log("VALIDATION_ERROR", "update-instance", instance_ctx=instance_id, extra={"auth_type": new_auth_type})
        return e
    if new_auth_type == "none" and auth_secret_ref is not None and auth_secret_ref.strip() != "":
        e = _err("VALIDATION_ERROR", "auth_secret_ref must be null/omitted when auth_type is 'none'")
        _enforce_and_log("VALIDATION_ERROR", "update-instance", instance_ctx=instance_id, extra={"auth_type": new_auth_type})
        return e

    # owner_user_id foreign key (must exist, must belong to same instance)
    if owner_user_id is not None:
        u = next((x for x in users if isinstance(x, dict) and x.get("id") == owner_user_id), None)
        if u is None:
            e = _err("NOT_FOUND", "owner_user_id does not reference an existing user")
            _enforce_and_log("NOT_FOUND", "update-instance", instance_ctx=instance_id, extra={"owner_user_id": owner_user_id})
            return e
        if u.get("instance_id") != instance_id:
            e = _err("VALIDATION_ERROR", "owner_user_id must belong to the same instance")
            _enforce_and_log("VALIDATION_ERROR", "update-instance", instance_ctx=instance_id, extra={"owner_user_id": owner_user_id})
            return e

    # No success without effect: require at least one mutable field provided
    if display_name is None and base_url is None and auth_type is None and auth_secret_ref is None and owner_user_id is None:
        e = _err("VALIDATION_ERROR", "No fields to update")
        _enforce_and_log("VALIDATION_ERROR", "update-instance", instance_ctx=instance_id)
        return e

    # Apply mutation
    changed = False
    if display_name is not None and display_name != inst.get("display_name"):
        inst["display_name"] = display_name
        changed = True
    if base_url is not None and base_url != inst.get("base_url"):
        inst["base_url"] = base_url
        changed = True
    if auth_type is not None and auth_type != inst.get("auth_type"):
        inst["auth_type"] = auth_type
        changed = True
    if auth_secret_ref is not None and auth_secret_ref != inst.get("auth_secret_ref"):
        inst["auth_secret_ref"] = auth_secret_ref
        changed = True
    if owner_user_id is not None and owner_user_id != inst.get("owner_user_id"):
        inst["owner_user_id"] = owner_user_id
        changed = True

    # Maintain constraint: cap_* defaults false (if missing)
    for k in ["cap_projects_enabled", "cap_variables_enabled", "cap_audit_enabled"]:
        if k not in inst or not isinstance(inst.get(k), bool):
            inst[k] = bool(inst.get(k)) if isinstance(inst.get(k), bool) else False
            # not counting as "changed" because it's internal normalization

    if not changed:
        # If request is a no-op, treat as conflict-free idempotent update and return the current row
        inst["updated_at"] = now
        instances[inst_idx] = inst
        try:
            _save("instances.json", instances)
        except Exception:
            e = _err("CONFLICT", "Could not persist update")
            _enforce_and_log("CONFLICT", "update-instance", instance_ctx=instance_id)
            return e
        _enforce_and_log("OK", "update-instance", instance_ctx=instance_id, extra={"idempotent": True})
        return {"instance": inst}

    inst["updated_at"] = now
    instances[inst_idx] = inst

    try:
        _save("instances.json", instances)
    except Exception:
        e = _err("CONFLICT", "Could not persist update")
        _enforce_and_log("CONFLICT", "update-instance", instance_ctx=instance_id)
        return e

    _enforce_and_log("OK", "update-instance", instance_ctx=instance_id)
    return {"instance": inst}

def set_instance_status(instance_id, status, last_error=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0295000" if __import__("os").path.isdir("./environment_mix/0295000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _append_request_log(endpoint, status_code, credential_id=None, instance_id=None, error_code=None, error_message=None, started_at=None):
        # Best-effort logging if a requests/audit collection exists.
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                rows = _ensure_list(_load(fname))
                ended = time.time()
                latency_ms = None
                if started_at is not None:
                    latency_ms = int(round((ended - started_at) * 1000))
                rows.append({
                    "id": f"req_{int(ended*1000)}",
                    "ts": _now(),
                    "endpoint": endpoint,
                    "instance_id": instance_id,
                    "credential_id": credential_id,
                    "status": status_code,
                    "error_code": error_code,
                    "error_message": error_message,
                    "latency_ms": latency_ms,
                })
                _save(fname, rows)
                break

    started = time.time()
    endpoint = "set-instance-status"

    # Validate inputs
    if not isinstance(instance_id, str) or not re.match(r"^n8n_inst_[0-9A-HJKMNP-TV-Z]{10,}$", instance_id):
        _append_request_log(endpoint, 400, instance_id=instance_id, error_code="VALIDATION_ERROR", error_message="instance_id is invalid", started_at=started)
        return _err("VALIDATION_ERROR", "instance_id is invalid", field="instance_id")

    allowed_status = {"provisioning", "ready", "error", "disabled"}
    if not isinstance(status, str) or status not in allowed_status:
        _append_request_log(endpoint, 400, instance_id=instance_id, error_code="VALIDATION_ERROR", error_message="status is invalid", started_at=started)
        return _err("VALIDATION_ERROR", "status is invalid", field="status", allowed=sorted(allowed_status))

    if last_error is not None and not isinstance(last_error, str):
        _append_request_log(endpoint, 400, instance_id=instance_id, error_code="VALIDATION_ERROR", error_message="last_error must be a string", started_at=started)
        return _err("VALIDATION_ERROR", "last_error must be a string", field="last_error")

    instances = _ensure_list(_load("instances.json"))

    idx = None
    for i, inst in enumerate(instances):
        if isinstance(inst, dict) and inst.get("id") == instance_id:
            idx = i
            break

    if idx is None:
        _append_request_log(endpoint, 404, instance_id=instance_id, error_code="NOT_FOUND", error_message="Instance not found", started_at=started)
        return _err("NOT_FOUND", "Instance not found", instance_id=instance_id)

    inst = instances[idx]
    current = inst.get("status")

    lifecycle = {
        "provisioning": {"ready", "error", "disabled"},
        "ready": {"error", "disabled"},
        "error": {"ready", "disabled"},
        "disabled": {"ready"},
    }

    # Idempotent if same status requested
    if current == status:
        # Still update audit-ish fields if transitioning to error with provided message? Business rules: persist when transitioning to error; no transition here.
        # We'll leave state unchanged except updated_at for a real "set" call.
        inst["updated_at"] = _now()
        instances[idx] = inst
        _save("instances.json", instances)
        _append_request_log(endpoint, 200, instance_id=instance_id, started_at=started)
        return {"instance": inst}

    if current not in lifecycle or status not in lifecycle.get(current, set()):
        _append_request_log(endpoint, 409, instance_id=instance_id, error_code="CONFLICT", error_message="Requested transition is not allowed", started_at=started)
        return _err(
            "CONFLICT",
            "Requested transition is not allowed",
            from_status=current,
            to_status=status,
            allowed=list(sorted(lifecycle.get(current, []))) if current in lifecycle else []
        )

    # Apply transition
    inst["status"] = status
    inst["updated_at"] = _now()

    if status == "ready":
        inst["last_healthcheck_at"] = _now()
        inst["last_error"] = None
    elif status == "error":
        # Schema expects last_error as object; tool supplies string. Store structured object with redacted message.
        msg = last_error if last_error is not None else "Unknown error"
        inst["last_error"] = {"message": msg}
    else:
        # For other statuses, do not touch last_error/healthcheck unless you want to clear? Keep as-is.
        pass

    instances[idx] = inst
    _save("instances.json", instances)

    _append_request_log(endpoint, 200, instance_id=instance_id, started_at=started)
    return {"instance": inst}

def whoami(instance_id=None, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0295000" if __import__("os").path.isdir("./environment_mix/0295000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_req_id():
        return "req_" + uuid.uuid4().hex

    def _append_request_log(endpoint, instance_id_ctx, status_code, credential_id=None, error_code=None, error_message=None, started=None):
        for fname in ("request_logs.json", "requests.json", "usage.json", "audit_log.json", "api_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                if not isinstance(logs, list):
                    logs = []
                finished = time.time()
                latency_ms = None
                if started is not None:
                    latency_ms = int(round((finished - started) * 1000))
                row = {
                    "id": _gen_req_id(),
                    "ts": _now(),
                    "endpoint": endpoint,
                    "instance_id": instance_id_ctx,
                    "credential_id": credential_id,
                    "status": status_code,
                    "latency_ms": latency_ms,
                }
                if error_code or error_message:
                    row["error"] = {"code": error_code, "message": error_message}
                logs.append(row)
                _save(fname, logs)
                return

    started = time.time()

    if instance_id is not None:
        if not isinstance(instance_id, str) or not re.match(r"^n8n_inst_[0-9A-HJKMNP-TV-Z]{10,}$", instance_id):
            _append_request_log("whoami", instance_id, 400, started=started, error_code="VALIDATION_ERROR", error_message="Invalid instance_id")
            return _err("VALIDATION_ERROR", "instance_id must match ^n8n_inst_[0-9A-HJKMNP-TV-Z]{10,}$")

    # AUTHENTICATION IS AMBIENT: there is no explicit credential parameter.
    # Refuse only if there is no viable context at all in the datastore (no instances).
    instances = _load("instances.json")
    if not isinstance(instances, list):
        instances = []

    # Choose a working combination: a ready instance if possible.
    inst = None
    if instance_id is not None:
        for r in instances:
            if isinstance(r, dict) and r.get("id") == instance_id:
                inst = r
                break
        if not inst:
            _append_request_log("whoami", instance_id, 404, started=started, error_code="NOT_FOUND", error_message="Instance not found")
            return _err("NOT_FOUND", "Instance not found", instance_id=instance_id)
    else:
        # prefer any ready instance
        for r in instances:
            if isinstance(r, dict) and r.get("status") == "ready":
                inst = r
                break
        if inst is None:
            # fall back to any instance (ambient caller can still exist; but vendor says AUTH_ERROR on missing/invalid credential;
            # with no credential parameter, interpret "no usable backend context" as unauthorized)
            for r in instances:
                if isinstance(r, dict) and r.get("id"):
                    inst = r
                    break

    if inst is None:
        _append_request_log("whoami", instance_id, 401, started=started, error_code="UNAUTHORIZED", error_message="No authenticated context available")
        return _err("UNAUTHORIZED", "AUTH_ERROR: missing/invalid credential")

    # Determine an identity: if instance has owner_user_id and that user exists, use it; otherwise anonymous service principal.
    users = _load("users.json")
    if not isinstance(users, list):
        users = []

    user = None
    owner_user_id = inst.get("owner_user_id")
    if owner_user_id:
        for u in users:
            if isinstance(u, dict) and u.get("id") == owner_user_id and u.get("instance_id") == inst.get("id"):
                user = u
                break

    identity = {
        "type": "service",
        "id": "integration_server",
        "display_name": "Integration Server",
    }
    scopes = ["instances:read"]
    if inst and inst.get("status") == "ready":
        scopes += ["workflows:read", "workflows:write", "users:read", "users:write"]
        if inst.get("cap_projects_enabled"):
            scopes += ["projects:read", "projects:write"]
        if inst.get("cap_variables_enabled"):
            scopes += ["variables:read", "variables:write"]
        if inst.get("cap_audit_enabled"):
            scopes += ["audit:generate"]

    if user:
        identity = {
            "type": "user",
            "id": user.get("id"),
            "email": user.get("email"),
            "role": user.get("role"),
            "status": user.get("status"),
            "instance_id": user.get("instance_id"),
        }

    # Rate-limit/quota consumption: only supported if a logs collection exists. No explicit limits are declared in schema,
    # so we report observed usage with null limits.
    consumption = {
        "rate_limit": {
            "window_seconds": 60,
            "limit": None,
            "used": None,
            "remaining": None,
        },
        "quota": {
            "period": "month",
            "limit": None,
            "used": None,
            "remaining": None,
        },
    }

    logs = None
    logs_fname = None
    for fname in ("request_logs.json", "requests.json", "usage.json", "audit_log.json", "api_logs.json"):
        if os.path.exists(os.path.join(_DB, fname)):
            logs = _load(fname)
            logs_fname = fname
            break

    if isinstance(logs, list):
        now = datetime.datetime.utcnow()
        # used in last 60s
        used_60 = 0
        used_month = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if inst and r.get("instance_id") not in (None, inst.get("id")):
                continue
            ts = r.get("ts") or r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                # accept Z ISO
                t = ts.replace("Z", "+00:00")
                dt = datetime.datetime.fromisoformat(t)
                if dt.tzinfo is not None:
                    dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            except Exception:
                continue
            delta = (now - dt).total_seconds()
            if 0 <= delta <= 60:
                used_60 += 1
            if dt.year == now.year and dt.month == now.month:
                used_month += 1

        consumption["rate_limit"]["used"] = used_60
        consumption["quota"]["used"] = used_month

    _append_request_log("whoami", inst.get("id") if inst else instance_id, 200, started=started)

    return {
        "identity": identity,
        "instance": {
            "id": inst.get("id"),
            "display_name": inst.get("display_name"),
            "base_url": inst.get("base_url"),
            "status": inst.get("status"),
            "cap_projects_enabled": inst.get("cap_projects_enabled"),
            "cap_variables_enabled": inst.get("cap_variables_enabled"),
            "cap_audit_enabled": inst.get("cap_audit_enabled"),
        } if inst else None,
        "scopes": sorted(set(scopes)),
        "consumption": consumption,
    }
